import React, { useState, useEffect, useCallback } from 'react';
import { API_ENDPOINTS } from '@/config/api';
import { useToast } from '@/components/Toast';
import './CategoryPage.css';
import { AlertDialog, AlertDialogContent, AlertDialogHeader, AlertDialogFooter, AlertDialogTitle, AlertDialogCancel, AlertDialogAction } from "@/components/ui/alert-dialog";

const EMOJI_OPTIONS = [
  '📌','🍽️','🏥','📚','🛒','🔧','🚗','🏠','💇','💪','📱','👔','🔩','🎭',
  '🤝','⚡','🌿','🧁','🐾','💼','🎓','🏋️','🧹','💊','🎨','🛡️','🔑','📦',
  '🎪','🌺','🍕','☕','🎸','📷','🏊','🧘','🎯','🏪','🌟','💈',
];



/* ── Add Category Form Panel ────────────────────────────────── */
function AddCategoryForm({ onSaved, onCancel }) {
  const [name, setName]     = useState('');
  const [icon, setIcon]     = useState('📌');
  const [saving, setSaving] = useState(false);
  const { show } = useToast();

  const handleSubmit = async () => {
    if (!name.trim()) { show('Nama kategori wajib diisi', 'error'); return; }
    setSaving(true);
    try {
      await API_ENDPOINTS.createCategory(name.trim(), icon);
      show(`Kategori "${name}" berhasil ditambahkan! 🎉`, 'success');
      setName('');
      setIcon('📌');
      onSaved();
    } catch (e) {
      show(e.message || 'Gagal menambah kategori', 'error');
    }
    setSaving(false);
  };

  return (
    <div className="cp-add-panel">
      <div className="cp-add-panel-header">
        <h3>➕ Tambah Kategori Baru</h3>
        <button className="cp-close-btn" onClick={onCancel}>×</button>
      </div>

      <div className="cp-add-panel-body">
        {/* Name input */}
        <div className="cp-form-group">
          <label className="cp-form-label">Nama Kategori <span className="cp-req">*</span></label>
          <input
            className="cp-form-input"
            value={name}
            onChange={e => setName(e.target.value)}
            placeholder="Cth: Jasa Catering, Taman Bermain, ..."
            onKeyDown={e => e.key === 'Enter' && handleSubmit()}
            autoFocus
          />
        </div>

        {/* Emoji picker */}
        <div className="cp-form-group">
          <label className="cp-form-label">
            Pilih Ikon &nbsp;
            <span className="cp-icon-preview">{icon}</span>
          </label>
          <div className="cp-emoji-grid">
            {EMOJI_OPTIONS.map(em => (
              <button
                key={em}
                className={`cp-emoji-btn ${icon === em ? 'selected' : ''}`}
                onClick={() => setIcon(em)}
                title={em}
              >
                {em}
              </button>
            ))}
          </div>
        </div>

        {/* Preview */}
        <div className="cp-preview">
          <span className="cp-preview-label">Preview:</span>
          <div className="cp-preview-card">
            <div className="cp-preview-icon">{icon}</div>
            <div className="cp-preview-name">{name || 'Nama Kategori'}</div>
          </div>
        </div>
      </div>

      <div className="cp-add-panel-footer">
        <button className="cp-btn cp-btn-secondary" onClick={onCancel}>Batal</button>
        <button
          className="cp-btn cp-btn-primary"
          onClick={handleSubmit}
          disabled={saving || !name.trim()}
        >
          {saving ? '⏳ Menyimpan...' : `${icon} Simpan Kategori`}
        </button>
      </div>
    </div>
  );
}

/* ── Category Card ──────────────────────────────────────────── */
function CategoryCard({ cat, count, isActive, isCustom, onSelect, onDelete, delay }) {
  return (
    <div
      className={`cp-cat-card ${isActive ? 'active' : ''} ${isCustom ? 'custom' : ''}`}
      style={{ animationDelay: `${delay}s` }}
      onClick={() => onSelect(cat)}
    >
      {isCustom && <span className="cp-custom-badge">Custom</span>}
      {isCustom && (
        <button
          className="cp-del-btn"
          title="Hapus kategori"
          onClick={e => { e.stopPropagation(); onDelete(cat); }}
        >
          🗑️
        </button>
      )}
      <div className="cp-cat-icon">{cat.icon}</div>
      <div className="cp-cat-name">{cat.nama}</div>
      <div className={`cp-cat-count ${count > 0 ? 'has-items' : ''}`}>
        {count > 0 ? `${count} listing` : 'Kosong'}
      </div>
    </div>
  );
}

/* ── Main CategoryPage ──────────────────────────────────────── */
export default function YellowCategoryPage({ activeCategory = '', onSelectCategory, embedded = false }) {
  const [categories, setCategories] = useState([]);
  const [catCounts, setCatCounts]   = useState({});
  const [loading, setLoading]       = useState(true);
  const [showAdd, setShowAdd]       = useState(false);
  const { show } = useToast();

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const [cats, stats] = await Promise.all([
        API_ENDPOINTS.getCategories(),
        API_ENDPOINTS.getStats(),
      ]);
      setCategories(cats);
      const counts = {};
      stats.by_category.forEach(c => { counts[c.kategori] = c.count; });
      setCatCounts(counts);
    } catch {
      show('Gagal memuat data kategori', 'error');
    }
    setLoading(false);
  }, []);

  useEffect(() => { loadData(); }, [loadData]);

 const [openDelete, setOpenDelete] = useState(false);
 const [selectedCat, setSelectedCat] = useState(null);

  const confirmDelete = async () => {
  if (!selectedCat) return;

  try {
    await API_ENDPOINTS.deleteCategory(selectedCat.id);
    show(`Kategori "${selectedCat.nama}" dihapus`, 'success');
    setOpenDelete(false);
    setSelectedCat(null);
    loadData();
  } catch (e) {
    show(e.message || 'Gagal menghapus', 'error');
  }};

  const handleDelete = async (cat) => {
    if (!cat.is_custom) { show('Kategori bawaan tidak bisa dihapus', 'error'); return; }
    setSelectedCat(cat);
    setOpenDelete(true);
  };  
     

  const handleSelect = (cat) => {
    if (onSelectCategory) onSelectCategory(cat.nama);
  };

  const defaultCats = categories.filter(c => !c.is_custom);
  const customCats  = categories.filter(c => c.is_custom);
  const totalListings = Object.values(catCounts).reduce((a, b) => a + b, 0);

  if (loading) {
    return (
      <div className={`cp-wrap ${embedded ? 'embedded' : ''}`}>
        <div className="cp-loading">
          <div className="cp-spinner" />
          <span>Memuat kategori...</span>
        </div>
      </div>
    );
  }

  return (
    <div className={`cp-wrap ${embedded ? 'embedded' : ''}`}>

      {/* Header — only shown when not embedded */}
      {!embedded && (
        <div className="cp-header">
          <div className="cp-header-left">
            <h1 className="cp-title">🗂️ Kategori Bidang Usaha</h1>
            <p className="cp-subtitle">
              {categories.length} kategori tersedia · {totalListings} total listing
            </p>
          </div>
          <button className="cp-btn cp-btn-primary" onClick={() => setShowAdd(v => !v)}>
            {showAdd ? '− Tutup Form' : '➕ Tambah Kategori'}
          </button>
        </div>
      )}

      {/* Embedded header */}
      {embedded && (
        <div className="cp-section-header">
          <span className="cp-section-title">Kelola Kategori</span>
          <button
            className="cp-btn-sm cp-btn-primary"
            onClick={() => setShowAdd(v => !v)}
          >
            {showAdd ? '−' : '+'} Tambah
          </button>
        </div>
      )}

      {/* Add form */}
      {showAdd && (
        <AddCategoryForm
          onSaved={() => { setShowAdd(false); loadData(); }}
          onCancel={() => setShowAdd(false)}
        />
      )}

      {/* Stats bar */}
      <div className="cp-stats-row">
        <div className="cp-stat">
          <span className="cp-stat-val">{categories.length}</span>
          <span className="cp-stat-lbl">Total Kategori</span>
        </div>
        <div className="cp-stat">
          <span className="cp-stat-val">{defaultCats.length}</span>
          <span className="cp-stat-lbl">Kategori Bawaan</span>
        </div>
        <div className="cp-stat">
          <span className="cp-stat-val">{customCats.length}</span>
          <span className="cp-stat-lbl">Kategori Custom</span>
        </div>
        <div className="cp-stat">
          <span className="cp-stat-val">{totalListings}</span>
          <span className="cp-stat-lbl">Total Listing</span>
        </div>
      </div>

      {/* ── Default categories ── */}
      <div className="cp-section">
        <div className="cp-section-label">
          Kategori Bawaan
          <span className="cp-section-count">{defaultCats.length}</span>
        </div>
        <div className="cp-grid">
          {defaultCats.map((cat, i) => (
            <CategoryCard
              key={cat.id}
              cat={cat}
              count={catCounts[cat.nama] || 0}
              isActive={activeCategory === cat.nama}
              isCustom={false}
              onSelect={handleSelect}
              onDelete={handleDelete}
              delay={i * 0.03}
            />
          ))}
        </div>
      </div>

      {/* ── Custom categories ── */}
      <div className="cp-section">
        <div className="cp-section-label">
          Kategori Custom
          <span className="cp-section-count">{customCats.length}</span>
        </div>

        {customCats.length === 0 && !showAdd ? (
          <div className="cp-empty-custom">
            <span>Belum ada kategori custom.</span>
            <button
              className="cp-btn cp-btn-secondary"
              onClick={() => setShowAdd(true)}
            >
              ➕ Tambah Sekarang
            </button>
          </div>
        ) : (
          <div className="cp-grid">
            {customCats.map((cat, i) => (
              <CategoryCard
                key={cat.id}
                cat={cat}
                count={catCounts[cat.nama] || 0}
                isActive={activeCategory === cat.nama}
                isCustom={true}
                onSelect={handleSelect}
                onDelete={handleDelete}
                delay={i * 0.03}
              />
            ))}

            {/* Always show "add" card at end */}
            <div className="cp-add-card" onClick={() => setShowAdd(true)}>
              <div className="cp-add-icon">＋</div>
              <div className="cp-add-label">Tambah Kategori Baru</div>
            </div>
          </div>
        )}
      </div>
    {/* BULK DELETE CONFIRMATION */}
     <AlertDialog open={openDelete} onOpenChange={setOpenDelete}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>
            Hapus kategori "{selectedCat?.nama}"?
          </AlertDialogTitle>
          <p className="text-sm text-gray-500">
            Listing dalam kategori ini akan terhapus.
          </p>
        </AlertDialogHeader>

        <AlertDialogFooter>
          <AlertDialogCancel>Batal</AlertDialogCancel>

          <AlertDialogAction
            className="bg-red-600 hover:bg-red-700 text-white"
            onClick={confirmDelete}
          >
            Hapus
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>

    </div>
  );
}
