import React, { useRef, useState, useEffect } from 'react';
import { Mic, Square, Trash2, Play, Pause } from 'lucide-react';

const formatTime = (sec) => {
  const s = Math.floor(sec % 60).toString().padStart(2, '0');
  const m = Math.floor(sec / 60).toString().padStart(2, '0');
  return `${m}:${s}`;
};

/**
 * VoiceRecorder — rekam voice note pakai MediaRecorder API (mirip voice note WhatsApp).
 *
 * Props:
 * - onRecorded(blob, durationSec) — dipanggil setelah user selesai rekam & simpan
 * - onClear() — dipanggil saat rekaman dihapus
 * - disabled — nonaktifkan tombol rekam
 */
const VoiceRecorder = ({ onRecorded, onClear, disabled = false }) => {
  const [status, setStatus] = useState('idle'); // idle | recording | recorded
  const [seconds, setSeconds] = useState(0);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState(null);

  const mediaRecorderRef = useRef(null);
  const chunksRef = useRef([]);
  const streamRef = useRef(null);
  const timerRef = useRef(null);
  const audioRef = useRef(null);

  useEffect(() => {
    return () => {
      clearInterval(timerRef.current);
      streamRef.current?.getTracks().forEach(t => t.stop());
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
    // Cleanup hanya perlu dijalankan saat unmount, bukan setiap kali previewUrl berubah
    // eslint-disable-next-line
  }, []);

  const startRecording = async () => {
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      chunksRef.current = [];

      const mimeType = MediaRecorder.isTypeSupported('audio/webm')
        ? 'audio/webm'
        : (MediaRecorder.isTypeSupported('audio/mp4') ? 'audio/mp4' : '');
      const recorder = mimeType
        ? new MediaRecorder(stream, { mimeType })
        : new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };
      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: recorder.mimeType || 'audio/webm' });
        const url = URL.createObjectURL(blob);
        setPreviewUrl(url);
        setStatus('recorded');
        streamRef.current?.getTracks().forEach(t => t.stop());
      };

      recorder.start();
      setStatus('recording');
      setSeconds(0);
      timerRef.current = setInterval(() => setSeconds(s => s + 1), 1000);
    } catch (err) {
      console.error('Gagal akses microphone', err);
      setError('Tidak bisa mengakses microphone. Pastikan izin microphone diaktifkan.');
    }
  };

  const stopRecording = () => {
    clearInterval(timerRef.current);
    mediaRecorderRef.current?.stop();
  };

  const handleSave = () => {
    if (!chunksRef.current.length) return;
    const recorder = mediaRecorderRef.current;
    const blob = new Blob(chunksRef.current, { type: recorder?.mimeType || 'audio/webm' });
    onRecorded?.(blob, seconds);
  };

  const handleClear = () => {
    clearInterval(timerRef.current);
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(null);
    setStatus('idle');
    setSeconds(0);
    setIsPlaying(false);
    chunksRef.current = [];
    onClear?.();
  };

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
  };

  if (status === 'idle') {
    return (
      <div className="space-y-1">
        <button
          type="button"
          onClick={startRecording}
          disabled={disabled}
          className="flex items-center gap-2 px-3 py-2 text-sm bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 hover:border-red-300 transition-colors shadow-sm disabled:opacity-50"
        >
          <Mic className="w-4 h-4 text-red-500" />
          <span className="text-gray-600 dark:text-gray-400">Rekam Voice Note</span>
        </button>
        {error && <p className="text-xs text-red-500">{error}</p>}
      </div>
    );
  }

  if (status === 'recording') {
    return (
      <div className="flex items-center gap-3 px-3 py-2 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
        <span className="relative flex h-3 w-3">
          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75" />
          <span className="relative inline-flex rounded-full h-3 w-3 bg-red-500" />
        </span>
        <span className="text-sm font-medium text-red-700 dark:text-red-300 tabular-nums">{formatTime(seconds)}</span>
        <span className="text-xs text-red-500 flex-1">Merekam...</span>
        <button
          type="button"
          onClick={stopRecording}
          className="flex items-center gap-1.5 px-3 py-1.5 text-xs bg-red-500 hover:bg-red-600 text-white rounded-lg"
        >
          <Square className="w-3 h-3" /> Stop
        </button>
      </div>
    );
  }

  // status === 'recorded'
  return (
    <div className="flex items-center gap-3 px-3 py-2 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
      <button
        type="button"
        onClick={togglePlay}
        className="flex-shrink-0 w-8 h-8 rounded-full bg-blue-500 hover:bg-blue-600 text-white flex items-center justify-center"
      >
        {isPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4 ml-0.5" />}
      </button>
      <audio
        ref={audioRef}
        src={previewUrl}
        onPlay={() => setIsPlaying(true)}
        onPause={() => setIsPlaying(false)}
        onEnded={() => setIsPlaying(false)}
        className="hidden"
      />
      <div className="flex-1">
        <p className="text-xs text-blue-700 dark:text-blue-300 font-medium">Voice note siap ({formatTime(seconds)})</p>
        <p className="text-[10px] text-blue-500">Belum disimpan — klik Gunakan untuk melampirkan</p>
      </div>
      <button
        type="button"
        onClick={handleSave}
        className="px-2.5 py-1.5 text-xs bg-green-500 hover:bg-green-600 text-white rounded-lg"
      >
        Gunakan
      </button>
      <button
        type="button"
        onClick={handleClear}
        className="p-1.5 text-gray-400 hover:text-red-500"
      >
        <Trash2 className="w-3.5 h-3.5" />
      </button>
    </div>
  );
};

export default VoiceRecorder;
