import React, { useState } from 'react';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Plus, Edit, Trash2 } from 'lucide-react';
import { toast } from '../hooks/use-toast';

// Template default untuk sistem
const DEFAULT_TEMPLATES = [
  {
    id: 'token_registrasi',
    name: '🔐 Token Registrasi',
    message: `Halo *{nama_warga}*,

Berikut adalah token registrasi Anda:

🔑 Token: *{token}*
📱 WhatsApp: {whatsapp}
🏠 Blok/Rumah: {blok_rumah}

Silakan kunjungi {link_registrasi} untuk menyelesaikan pendaftaran.

_Token ini berlaku 24 jam._

Terima kasih,
*Pengurus RT*`,
    isSystem: true,
  },
  {
    id: 'tagihan_ipl',
    name: '💰 Tagihan IPL',
    message: `Halo Bapak/Ibu *{nama_warga}*,

Berikut adalah tagihan IPL bulan *{bulan}*:

📋 Periode: {periode}
💵 Nominal: Rp {nominal}
📅 Jatuh tempo: {tanggal_jatuh_tempo}

Pembayaran dapat dilakukan melalui:
🏦 Transfer Bank💵 Tunai� QRIS

Terima kasih atas kerjasamanya.

*Pengurus RT*`,
    isSystem: true,
  },
  {
    id: 'tagihan_ipl_tunggakan',
    name: '💰 Tagihan IPL Tunggakan',
    message: `Halo Bapak/Ibu *{nama_warga}*,

Berikut adalah rincian tunggakan IPL Anda:

{detail_tagihan}

💰 *Total Tunggakan: Rp {total_tunggakan}*
📅 Harap segera dilunasi

Pembayaran dapat dilakukan melalui:
🏦 Transfer Bank
💵 Tunai
🤳 QRIS

Terima kasih atas kerjasamanya.

*Pengurus RT*`,
    isSystem: true,
  },
  {
    id: 'pengumuman_umum',
    name: '📢 Pengumuman Umum',
    message: `Halo warga,

{isi_pengumuman}

Terima kasih,
*Pengurus RT*`,
    isSystem: true,
  },
];

const MessageTemplateSelector = ({ value, onChange }) => {
  const [customTemplates, setCustomTemplates] = useState(() => {
    const saved = localStorage.getItem('whatsapp_custom_templates');
    return saved ? JSON.parse(saved) : [];
  });
  
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState(null);
  const [templateName, setTemplateName] = useState('');
  const [templateMessage, setTemplateMessage] = useState('');

  const allTemplates = [...DEFAULT_TEMPLATES, ...customTemplates];

  const handleSelectTemplate = (templateId) => {
    const template = allTemplates.find((t) => t.id === templateId);
    if (template) {
      onChange(template.message);
    }
  };

  const handleSaveCustomTemplate = () => {
    if (!templateName.trim() || !templateMessage.trim()) {
      toast({ title: 'Lengkapi data', description: 'Nama dan pesan template harus diisi', variant: 'destructive' });
      return;
    }

    const newTemplate = {
      id: editingTemplate?.id || `custom_${Date.now()}`,
      name: templateName,
      message: templateMessage,
      isSystem: false,
    };

    let updatedTemplates;
    if (editingTemplate) {
      updatedTemplates = customTemplates.map((t) => (t.id === editingTemplate.id ? newTemplate : t));
    } else {
      updatedTemplates = [...customTemplates, newTemplate];
    }

    setCustomTemplates(updatedTemplates);
    localStorage.setItem('whatsapp_custom_templates', JSON.stringify(updatedTemplates));
    
    toast({ title: 'Template disimpan', description: 'Template berhasil disimpan' });
    setDialogOpen(false);
    resetForm();
  };

  const handleEditTemplate = (template) => {
    setEditingTemplate(template);
    setTemplateName(template.name);
    setTemplateMessage(template.message);
    setDialogOpen(true);
  };

  const handleDeleteTemplate = (templateId) => {
    const updatedTemplates = customTemplates.filter((t) => t.id !== templateId);
    setCustomTemplates(updatedTemplates);
    localStorage.setItem('whatsapp_custom_templates', JSON.stringify(updatedTemplates));
    toast({ title: 'Template dihapus', description: 'Template berhasil dihapus' });
  };

  const resetForm = () => {
    setEditingTemplate(null);
    setTemplateName('');
    setTemplateMessage('');
  };

  return (
    <div className="flex gap-2">
      <Select onValueChange={handleSelectTemplate}>
        <SelectTrigger className="w-full">
          <SelectValue placeholder="Pilih template pesan..." />
        </SelectTrigger>
        <SelectContent>
          <div className="px-2 py-1.5 text-xs font-semibold text-gray-500">Template Sistem</div>
          {DEFAULT_TEMPLATES.map((template) => (
            <SelectItem key={template.id} value={template.id}>
              {template.name}
            </SelectItem>
          ))}
          
          {customTemplates.length > 0 && (
            <>
              <div className="px-2 py-1.5 text-xs font-semibold text-gray-500 border-t mt-2">Template Custom</div>
              {customTemplates.map((template) => (
                <SelectItem key={template.id} value={template.id}>
                  {template.name}
                </SelectItem>
              ))}
            </>
          )}
        </SelectContent>
      </Select>

      <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
        <DialogTrigger asChild>
          <Button variant="outline" size="icon">
            <Plus className="h-4 w-4" />
          </Button>
        </DialogTrigger>
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingTemplate ? 'Edit Template' : 'Buat Template Baru'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Nama Template</Label>
              <Input
                placeholder="Contoh: Pengumuman Iuran"
                value={templateName}
                onChange={(e) => setTemplateName(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label>Pesan Template</Label>
              <textarea
                className="w-full min-h-[200px] p-3 text-sm border rounded-md focus:outline-none focus:ring-2 focus:ring-cyan-500"
                placeholder="Tulis template pesan Anda di sini..."
                value={templateMessage}
                onChange={(e) => setTemplateMessage(e.target.value)}
              />
              <div className="text-xs text-gray-500 space-y-1">
                <p>💡 <strong>Variabel yang tersedia:</strong></p>
                <p>• <code>{'{nama_warga}'}</code> - Nama warga</p>
                <p>• <code>{'{token}'}</code> - Token registrasi</p>
                <p>• <code>{'{whatsapp}'}</code> - Nomor WhatsApp</p>
                <p>• <code>{'{blok_rumah}'}</code> - Blok/Nomor rumah</p>
                <p>• <code>{'{nominal}'}</code> - Nominal tagihan</p>
                <p>• <code>{'{bulan}'}</code> - Bulan tagihan</p>
                <p>• <code>{'{periode}'}</code> - Periode tagihan</p>
              </div>
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => { setDialogOpen(false); resetForm(); }}>
                Batal
              </Button>
              <Button onClick={handleSaveCustomTemplate}>
                {editingTemplate ? 'Update Template' : 'Simpan Template'}
              </Button>
            </div>

            {customTemplates.length > 0 && (
              <div className="border-t pt-4 mt-4">
                <Label className="mb-3 block">Template Custom Anda</Label>
                <div className="space-y-2">
                  {customTemplates.map((template) => (
                    <div key={template.id} className="flex items-center justify-between p-3 border rounded-lg hover:bg-gray-50 dark:hover:bg-gray-800">
                      <span className="text-sm font-medium">{template.name}</span>
                      <div className="flex gap-2">
                        <Button variant="ghost" size="sm" onClick={() => handleEditTemplate(template)}>
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button variant="ghost" size="sm" onClick={() => handleDeleteTemplate(template.id)}>
                          <Trash2 className="h-4 w-4 text-red-500" />
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default MessageTemplateSelector;
