import React from 'react'
import { Ico } from './Icons.jsx'
import { useCMS } from './cmsContent.jsx'
import { useAppSettings } from '../../contexts/AppSettingsContext'

// CTA landingpage3 — tombol "Mulai gratis 14 hari" dihilangkan; "Jadwalkan
// demo" mengarah ke WA support default vendor (Vendor > Settings).
export default function CTA() {
  const c = useCMS('cta')
  const { supportWhatsapp } = useAppSettings()
  const demoHref = supportWhatsapp ? `https://wa.me/${supportWhatsapp}` : (c.cta_secondary?.href || '#')
  return (
    <section className="section" id="cta" style={{paddingTop: 40, paddingBottom: 60}}>
      <div className="container">
        <div className="cta-card">
          <span className="kicker" style={{color:'var(--mustard)'}}>{c.kicker}</span>
          <h2 style={{marginTop:18}} dangerouslySetInnerHTML={{ __html: c.title_html }} />
          <p>{c.description}</p>
          <div className="cta-row">
            <a href={demoHref} target="_blank" rel="noopener noreferrer" className="btn btn-primary btn-lg">
              {c.cta_secondary?.label || 'Jadwalkan demo'} <Ico.Phone />
            </a>
          </div>
        </div>
      </div>
    </section>
  )
}
