import React from 'react'
import { Ico } from './Icons.jsx'
import { useCMS } from './cmsContent.jsx'

export default function HowItWorks() {
  const c = useCMS('how_it_works')
  const steps = c.steps || []
  return (
    <section className="section" id="cara" style={{paddingBottom: 80}}>
      <div className="container">
        <div className="section-head">
          <span className="kicker">{c.kicker}</span>
          <h2 dangerouslySetInnerHTML={{ __html: c.title_html }} />
          <p>{c.description}</p>
        </div>
        <div className="steps">
          {steps.map((s, i) => {
            const Icon = Ico[s.icon] || Ico.Map
            return (
              <div className="step" key={i}>
                <div className="step-icon"><Icon /></div>
                <div className="step-num">{s.number}</div>
                <h4 dangerouslySetInnerHTML={{ __html: s.title_html }} />
                <p>{s.description}</p>
              </div>
            )
          })}
        </div>
      </div>
    </section>
  )
}
