import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useRWFilter } from '../../contexts/RWFilterContext';
import { API_BASE_URL } from '../../config/api';
import {
  Bell, Plus, Pencil, Trash2, RefreshCw, Eye, Send, Building2, Megaphone
} from 'lucide-react';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';

const STATUS_COLORS = {
  draft: 'border-gray-400 text-gray-500 bg-[var(--rw-bg-card-alt)] dark:bg-gray-700',
  published: 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20',
  archived: 'border-amber-400 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
};

const TIPE_COLORS = {
  info: 'border-blue-400 text-blue-600 bg-blue-50 dark:bg-blue-900/20',
  penting: 'border-amber-500 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
  darurat: 'border-red-500 text-red-600 bg-red-50 dark:bg-red-900/20',
  kegiatan: 'border-purple-400 text-purple-600 bg-purple-50 dark:bg-purple-900/20',
};

const PengumumanRW = () => {
  const { token } = useAuth();
  const { rtList } = useRWFilter();
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filterStatus, setFilterStatus] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [viewItem, setViewItem] = useState(null);
  const [saving, setSaving] = useState(false);
  const [inboxKelurahan, setInboxKelurahan] = useState([]);
  const [inboxLoading, setInboxLoading] = useState(false);
  const [inboxViewItem, setInboxViewItem] = useState(null);
  const [form, setForm] = useState({
    judul: '', isi: '', tipe: 'info', target: 'all',
    level: 'RW', status: 'draft'
  });

  useEffect(() => { fetchData(); fetchInbox(); }, [token]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = filterStatus ? `?status=${filterStatus}` : '';
      const res = await axios.get(`${API_BASE_URL}/api/rw/announcements${params}`, { headers });
      setData(res.data?.data || []);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchInbox = async () => {
    try {
      setInboxLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const res = await axios.get(`${API_BASE_URL}/api/pengumuman/inbox-rw`, { headers });
      setInboxKelurahan(res.data?.data || []);
    } catch {
      setInboxKelurahan([]);
    } finally {
      setInboxLoading(false);
    }
  };

  const openAdd = () => {
    setEditItem(null);
    setForm({ judul: '', isi: '', tipe: 'info', target: 'all', level: 'RW', status: 'draft' });
    setShowForm(true);
  };

  const openEdit = (item) => {
    setEditItem(item);
    // Reconstruct select value: jika target='rt', gunakan target_rt_blok sebagai select value
    const targetVal = item.target === 'rt' ? (item.target_rt_blok || 'all') : item.target;
    setForm({
      judul: item.judul, isi: item.isi, tipe: item.tipe,
      target: targetVal, level: item.level || 'RW', status: item.status
    });
    setShowForm(true);
  };

  const handleSave = async () => {
    if (!form.judul || !form.isi) return;
    try {
      setSaving(true);
      const headers = { Authorization: `Bearer ${token}` };
      // Jika target adalah UUID dari rtList → simpan sebagai target='rt' + target_rt_blok=<uuid>
      const isRtSpecific = rtList.some(r => r.id === form.target);
      const payload = {
        ...form,
        target: isRtSpecific ? 'rt' : form.target,
        target_rt_blok: isRtSpecific ? form.target : null,
        level: 'RW',
      };
      if (editItem) {
        await axios.put(`${API_BASE_URL}/api/pengumuman/${editItem.id}`, payload, { headers });
      } else {
        await axios.post(`${API_BASE_URL}/api/pengumuman`, payload, { headers });
      }
      setShowForm(false);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menyimpan');
    } finally {
      setSaving(false);
    }
  };

  const handlePublish = async (id) => {
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.post(`${API_BASE_URL}/api/pengumuman/${id}/publish`, {}, { headers });
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal mempublish');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Hapus pengumuman ini?')) return;
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.delete(`${API_BASE_URL}/api/pengumuman/${id}`, { headers });
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menghapus');
    }
  };

  const formatDate = (d) => d
    ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
    : '-';

  if (loading) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat pengumuman...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Pengumuman</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-purple-500 to-violet-600 rounded-xl flex items-center justify-center shadow">
            <Bell className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Pengumuman RW</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Broadcast ke seluruh RT — {data.length} pengumuman</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchData} className="flex items-center gap-2 px-3 py-2 text-sm bg-[var(--rw-bg-card)] dark:bg-gray-800 border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          <button onClick={openAdd} className="flex items-center gap-2 px-4 py-2 bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white text-sm rounded-lg transition-colors">
            <Plus className="h-4 w-4" />Buat Pengumuman
          </button>
        </div>
      </div>

{/* Filter */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-4 flex gap-3 items-end">
        <div className="w-40">
          <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Filter Status</label>
          <Select value={filterStatus || "all"} onValueChange={v => { setFilterStatus(v === "all" ? "" : v); setTimeout(fetchData, 100); }}>
            <SelectTrigger><SelectValue placeholder="Semua Status" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Semua Status</SelectItem>
              <SelectItem value="draft">Draft</SelectItem>
              <SelectItem value="published">Published</SelectItem>
              <SelectItem value="archived">Archived</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Table */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="p-4 border-b border-[var(--rw-border)] dark:border-gray-700">
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">
            Daftar Pengumuman ({data.length})
          </h3>
        </div>
        {data.length > 0 ? (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Judul</TableHead>
                <TableHead>Tipe</TableHead>
                <TableHead>Target</TableHead>
                <TableHead>Level</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Dibuat Oleh</TableHead>
                <TableHead>Tanggal</TableHead>
                <TableHead className="text-center">Aksi</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {data.map((p) => (
                <TableRow key={p.id}>
                  <TableCell className="font-medium text-gray-900 dark:text-white max-w-[200px]">
                    <span className="truncate block">{p.judul}</span>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={TIPE_COLORS[p.tipe] || ''}>
                      {p.tipe}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-sm">
                    {p.target === 'all' ? 'Semua RT'
                      : rtList.find(r => r.id === p.target)?.name || p.target}
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className="border-blue-400 text-blue-600 bg-blue-50 dark:bg-blue-900/20">
                      {p.level}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={STATUS_COLORS[p.status] || ''}>
                      {p.status}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-sm text-gray-500 dark:text-gray-400">{p.creator_name || '-'}</TableCell>
                  <TableCell className="text-sm text-gray-500 dark:text-gray-400">{formatDate(p.created_at)}</TableCell>
                  <TableCell className="text-center">
                    <div className="flex items-center justify-center gap-1">
                      <button onClick={() => setViewItem(p)} className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded">
                        <Eye className="h-3.5 w-3.5" />
                      </button>
                      {p.status === 'draft' && (
                        <button onClick={() => handlePublish(p.id)} className="p-1.5 text-green-500 hover:bg-green-50 dark:hover:bg-green-900/20 rounded" title="Publish">
                          <Send className="h-3.5 w-3.5" />
                        </button>
                      )}
                      <button onClick={() => openEdit(p)} className="p-1.5 text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded">
                        <Pencil className="h-3.5 w-3.5" />
                      </button>
                      <button onClick={() => handleDelete(p.id)} className="p-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded">
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="text-center py-12">
            <Bell className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <p className="text-gray-500 dark:text-gray-400">Belum ada pengumuman</p>
          </div>
        )}
      </div>

      {/* Inbox Kelurahan */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="bg-gradient-to-r from-emerald-500 to-teal-600 p-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-white/20 rounded-lg flex items-center justify-center">
              <Megaphone className="h-4 w-4 text-white" />
            </div>
            <div>
              <h3 className="text-base font-semibold text-white">Broadcast dari Kelurahan</h3>
              <p className="text-emerald-100 text-xs">{inboxKelurahan.length} pengumuman masuk</p>
            </div>
          </div>
          <button onClick={fetchInbox} className="p-2 text-white/80 hover:text-white hover:bg-white/10 rounded-lg transition-colors">
            <RefreshCw className={`h-4 w-4 ${inboxLoading ? 'animate-spin' : ''}`} />
          </button>
        </div>

        {inboxLoading ? (
          <div className="flex items-center justify-center py-8">
            <div className="w-8 h-8 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : inboxKelurahan.length > 0 ? (
          <div className="divide-y divide-gray-100 dark:divide-gray-700">
            {inboxKelurahan.map((item) => (
              <div key={item.id} className="p-4 flex items-start gap-3 hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700/50 transition-colors">
                <div className={`mt-0.5 w-2 h-2 rounded-full flex-shrink-0 ${
                  item.tipe === 'darurat' ? 'bg-red-500' :
                  item.tipe === 'penting' ? 'bg-amber-500' :
                  item.tipe === 'kegiatan' ? 'bg-purple-500' : 'bg-blue-500'
                }`} />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap mb-1">
                    <span className="font-medium text-gray-900 dark:text-white text-sm">{item.judul}</span>
                    <Badge variant="outline" className={TIPE_COLORS[item.tipe] || ''}>
                      {item.tipe}
                    </Badge>
                  </div>
                  <p className="text-xs text-gray-500 dark:text-gray-400 line-clamp-2">{item.isi}</p>
                  <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">
                    <Building2 className="h-3 w-3 inline mr-1" />
                    {item.creator_name || 'Kelurahan'} · {formatDate(item.published_at || item.created_at)}
                  </p>
                </div>
                <button
                  onClick={() => setInboxViewItem(item)}
                  className="p-1.5 text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded flex-shrink-0"
                >
                  <Eye className="h-3.5 w-3.5" />
                </button>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-10">
            <Megaphone className="h-10 w-10 text-gray-300 dark:text-gray-600 mx-auto mb-2" />
            <p className="text-gray-500 dark:text-gray-400 text-sm">Belum ada broadcast dari Kelurahan</p>
          </div>
        )}
      </div>

      {/* Inbox Kelurahan View Dialog */}
      <Dialog open={!!inboxViewItem} onOpenChange={() => setInboxViewItem(null)}>
        <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Megaphone className="h-5 w-5 text-emerald-500" />
              {inboxViewItem?.judul}
            </DialogTitle>
          </DialogHeader>
          {inboxViewItem && (
            <div className="space-y-3 text-sm">
              <div className="flex gap-2 flex-wrap">
                <Badge variant="outline" className="border-emerald-500 text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20">
                  Kelurahan
                </Badge>
                <Badge variant="outline" className={TIPE_COLORS[inboxViewItem.tipe] || ''}>{inboxViewItem.tipe}</Badge>
              </div>
              <div className="text-gray-500 dark:text-gray-400 text-xs">
                Dari: {inboxViewItem.creator_name || 'Kelurahan'} · Dipublish: {formatDate(inboxViewItem.published_at || inboxViewItem.created_at)}
              </div>
              <div className="bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 rounded-lg p-4 text-gray-700 dark:text-gray-300 whitespace-pre-wrap">
                {inboxViewItem.isi}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Form Dialog */}
      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 max-w-lg">
          <DialogHeader>
            <DialogTitle>{editItem ? 'Edit Pengumuman' : 'Buat Pengumuman Baru'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div>
              <Label>Judul <span className="text-red-500">*</span></Label>
              <Input className="mt-1" value={form.judul} onChange={e => setForm(f => ({ ...f, judul: e.target.value }))} placeholder="Judul pengumuman..." />
            </div>
            <div>
              <Label>Isi Pengumuman <span className="text-red-500">*</span></Label>
              <Textarea className="mt-1" rows={4} value={form.isi} onChange={e => setForm(f => ({ ...f, isi: e.target.value }))} placeholder="Isi pengumuman..." />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Tipe</Label>
                <Select value={form.tipe} onValueChange={v => setForm(f => ({ ...f, tipe: v }))}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="info">Info</SelectItem>
                    <SelectItem value="penting">Penting</SelectItem>
                    <SelectItem value="darurat">Darurat</SelectItem>
                    <SelectItem value="kegiatan">Kegiatan</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Target</Label>
                <Select value={form.target} onValueChange={v => setForm(f => ({ ...f, target: v }))}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">Semua RT</SelectItem>
                    {rtList.map(rt => (
                      <SelectItem key={rt.id} value={rt.id}>{rt.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div>
              <Label>Status</Label>
              <Select value={form.status} onValueChange={v => setForm(f => ({ ...f, status: v }))}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="published">Publish Sekarang</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <button onClick={() => setShowForm(false)} className="px-4 py-2 text-sm border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-800">Batal</button>
            <button onClick={handleSave} disabled={saving} className="px-4 py-2 bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white text-sm rounded-lg disabled:opacity-50">
              {saving ? 'Menyimpan...' : 'Simpan'}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={!!viewItem} onOpenChange={() => setViewItem(null)}>
        <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Bell className="h-5 w-5 text-purple-500" />
              {viewItem?.judul}
            </DialogTitle>
          </DialogHeader>
          {viewItem && (
            <div className="space-y-3 text-sm">
              <div className="flex gap-2 flex-wrap">
                <Badge variant="outline" className={STATUS_COLORS[viewItem.status] || ''}>{viewItem.status}</Badge>
                <Badge variant="outline" className={TIPE_COLORS[viewItem.tipe] || ''}>{viewItem.tipe}</Badge>
                <Badge variant="outline">
                  Target: {viewItem.target === 'all' ? 'Semua RT'
                    : rtList.find(r => r.id === viewItem.target)?.name || viewItem.target}
                </Badge>
              </div>
              <div className="text-gray-500 dark:text-gray-400 text-xs">
                Dibuat: {formatDate(viewItem.created_at)} · Oleh: {viewItem.creator_name || '-'}
                {viewItem.published_at && ` · Dipublish: ${formatDate(viewItem.published_at)}`}
              </div>
              <div className="bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 rounded-lg p-4 text-gray-700 dark:text-gray-300 whitespace-pre-wrap">
                {viewItem.isi}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default PengumumanRW;
