import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";

const EMPTY_FORM = {
  nama_lengkap: "",
  email: "",
  country_code: "+62",
  whatsapp: "",
  jabatan: "",
  status: "active",
  jenis_kelamin: "",
  status_pegawai: "",
  awal_bekerja: "",
  nama_bank: "",
  nama_rekening: "",
  nomor_rekening: "",
  is_default_support: false,
};

export default function KaryawanForm({ open, onOpenChange, karyawan, onSaved }) {
  const { token } = useAuth(); // 🔐 JWT
  const [loading, setLoading] = useState(false);
  const [jenisKelaminOpsi, setJenisKelaminOpsi] = useState([]);
  const [statusPegawaiOpsi, setStatusPegawaiOpsi] = useState([]);

  const [form, setForm] = useState(EMPTY_FORM);

  // --------------------------------------------------
  // LOAD OPSI REFERENSI (Jenis Kelamin, Status Pegawai)
  // --------------------------------------------------
  useEffect(() => {
    if (!open) return;
    fetch(`${API_BASE_URL}/api/referensi/jenis-kelamin`)
      .then((r) => (r.ok ? r.json() : []))
      .then(setJenisKelaminOpsi)
      .catch(() => {});
    fetch(`${API_BASE_URL}/api/referensi/status-pegawai`)
      .then((r) => (r.ok ? r.json() : []))
      .then(setStatusPegawaiOpsi)
      .catch(() => {});
  }, [open]);

  // --------------------------------------------------
  // LOAD DATA SAAT EDIT
  // --------------------------------------------------
  useEffect(() => {
    if (karyawan) {
      setForm({
        nama_lengkap: karyawan.nama_lengkap || "",
        email: karyawan.email || "",
        country_code: karyawan.country_code || "+62",
        whatsapp: karyawan.whatsapp || "",
        jabatan: karyawan.jabatan || "",
        status: karyawan.status || "active",
        jenis_kelamin: karyawan.jenis_kelamin || "",
        status_pegawai: karyawan.status_pegawai || "",
        awal_bekerja: karyawan.awal_bekerja ? karyawan.awal_bekerja.split("T")[0] : "",
        nama_bank: karyawan.nama_bank || "",
        nama_rekening: karyawan.nama_rekening || "",
        nomor_rekening: karyawan.nomor_rekening || "",
        is_default_support: !!karyawan.is_default_support,
      });
    } else {
      setForm(EMPTY_FORM);
    }
  }, [karyawan]);

  // --------------------------------------------------
  // SAVE
  // --------------------------------------------------
  const save = async () => {
    if (!form.nama_lengkap.trim()) {
      toast.error("Nama lengkap harus diisi");
      return;
    }

    setLoading(true);

    const url = karyawan
      ? `${API_BASE_URL}/api/karyawan/${karyawan.id}`
      : `${API_BASE_URL}/api/karyawan`;

    const method = karyawan ? "PUT" : "POST";

    try {
      // Convert empty strings to null untuk optional fields
      const payload = {
        nama_lengkap: form.nama_lengkap || null,
        email: form.email || null,
        country_code: form.country_code,
        whatsapp: form.whatsapp || null,
        jabatan: form.jabatan || null,
        status: form.status,
        jenis_kelamin: form.jenis_kelamin || null,
        status_pegawai: form.status_pegawai || null,
        awal_bekerja: form.awal_bekerja ? form.awal_bekerja : null,
        nama_bank: form.nama_bank || null,
        nama_rekening: form.nama_rekening || null,
        nomor_rekening: form.nomor_rekening || null,
        is_default_support: form.is_default_support,
      };

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // 🔐 JWT
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        toast.error("Gagal menyimpan pegawai");
        setLoading(false);
        return;
      }

      toast.success(karyawan ? "Pegawai berhasil diperbarui!" : "Pegawai baru ditambahkan!");
      onSaved();
      onOpenChange(false);

    } catch (err) {
      toast.error("Tidak dapat terhubung ke server");
    }

    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl dark:bg-gray-900 dark:text-gray-100 max-h-screen overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{karyawan ? "Edit Pegawai" : "Tambah Pegawai"}</DialogTitle>
        </DialogHeader>

        <div className="space-y-3">

          {/* ROW 1: NAMA & EMAIL */}
          <div className="grid grid-cols-2 gap-3">
            <Input
              placeholder="Nama Lengkap"
              value={form.nama_lengkap}
              onChange={(e) => setForm({ ...form, nama_lengkap: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
            <Input
              placeholder="Email"
              type="email"
              value={form.email}
              onChange={(e) => setForm({ ...form, email: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* ROW 2: KODE NEGARA & WHATSAPP */}
          <div className="grid grid-cols-3 gap-3">
            <Input
              placeholder="Kode Negara"
              value={form.country_code}
              disabled
              className="dark:bg-gray-800 dark:text-gray-100"
            />
            <Input
              placeholder="Nomor WhatsApp"
              value={form.whatsapp}
              onChange={(e) => setForm({ ...form, whatsapp: e.target.value })}
              className="col-span-2 dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* ROW 3: JABATAN & STATUS */}
          <div className="grid grid-cols-2 gap-3">
            <Input
              placeholder="Jabatan"
              value={form.jabatan}
              onChange={(e) => setForm({ ...form, jabatan: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
            <select
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value })}
              className="
                w-full p-2 rounded-md border
                border-gray-300 dark:border-gray-700
                bg-[var(--rw-bg-card)] dark:bg-gray-800
                text-gray-900 dark:text-gray-100
                focus:outline-none focus:ring-2 focus:ring-cyan-500
              "
            >
              <option value="active">Aktif</option>
              <option value="inactive">Tidak Aktif</option>
            </select>
          </div>

          {/* ROW 3b: JENIS KELAMIN & STATUS PEGAWAI */}
          <div className="grid grid-cols-2 gap-3">
            <select
              value={form.jenis_kelamin}
              onChange={(e) => setForm({ ...form, jenis_kelamin: e.target.value })}
              className="w-full p-2 rounded-md border border-gray-300 dark:border-gray-700 bg-[var(--rw-bg-card)] dark:bg-gray-800 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-cyan-500"
            >
              <option value="">-- Jenis Kelamin --</option>
              {jenisKelaminOpsi.length > 0 ? (
                jenisKelaminOpsi.map((o) => <option key={o.id} value={o.nilai}>{o.label}</option>)
              ) : (
                <>
                  <option value="Laki-laki">Laki-laki</option>
                  <option value="Perempuan">Perempuan</option>
                </>
              )}
            </select>
            <select
              value={form.status_pegawai}
              onChange={(e) => setForm({ ...form, status_pegawai: e.target.value })}
              className="w-full p-2 rounded-md border border-gray-300 dark:border-gray-700 bg-[var(--rw-bg-card)] dark:bg-gray-800 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-cyan-500"
            >
              <option value="">-- Status Pegawai --</option>
              {statusPegawaiOpsi.length > 0 ? (
                statusPegawaiOpsi.map((o) => <option key={o.id} value={o.nilai}>{o.label}</option>)
              ) : (
                <>
                  <option value="Tetap">Tetap</option>
                  <option value="Kontrak">Kontrak</option>
                  <option value="Outsource">Outsource</option>
                </>
              )}
            </select>
          </div>

          {/* ROW 4: AWAL BEKERJA */}
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
              Awal Bekerja
            </label>
            <Input
              type="date"
              value={form.awal_bekerja}
              onChange={(e) => setForm({ ...form, awal_bekerja: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* ROW 5: NAMA BANK & NAMA REKENING */}
          <div className="grid grid-cols-2 gap-3">
            <Input
              placeholder="Nama Bank"
              value={form.nama_bank}
              onChange={(e) => setForm({ ...form, nama_bank: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
            <Input
              placeholder="Nama Rekening"
              value={form.nama_rekening}
              onChange={(e) => setForm({ ...form, nama_rekening: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* ROW 6: NOMOR REKENING */}
          <Input
            placeholder="Nomor Rekening"
            value={form.nomor_rekening}
            onChange={(e) => setForm({ ...form, nomor_rekening: e.target.value })}
            className="dark:bg-gray-800 dark:text-gray-100"
          />

          {/* KONTAK DEFAULT SUPPORT */}
          <div className="flex items-start gap-2.5 p-3 rounded-lg border border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-900/20">
            <input
              type="checkbox"
              id="is_default_support"
              checked={form.is_default_support}
              onChange={(e) => setForm({ ...form, is_default_support: e.target.checked })}
              className="w-4 h-4 mt-0.5 rounded border-gray-300"
            />
            <label htmlFor="is_default_support" className="text-xs text-gray-700 dark:text-gray-300 cursor-pointer">
              <span className="font-semibold">Kontak Default Support</span> — nomor WhatsApp pegawai ini
              dipakai untuk tombol "Butuh bantuan?" di halaman login Kelurahan.
              Hanya boleh satu pegawai yang dicentang; mencentang pegawai ini akan
              otomatis melepas centang dari pegawai lain.
            </label>
          </div>

          {/* BUTTONS */}
          <div className="flex gap-3 justify-end pt-4">
            <Button
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="dark:border-gray-700 dark:text-gray-200 dark:hover:bg-gray-800"
            >
              Batal
            </Button>
            <Button
              onClick={save}
              disabled={loading}
              className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white"
            >
              {loading ? "Menyimpan..." : "Simpan"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
