import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';

// Menggelapkan warna hex untuk sisi "dinding" pie 3D (efek bayangan/kedalaman)
const darkenColor = (hex, amount = 0.32) => {
  if (!hex || hex[0] !== '#') return hex;
  const num = parseInt(hex.slice(1), 16);
  let r = (num >> 16) & 255;
  let g = (num >> 8) & 255;
  let b = num & 255;
  r = Math.max(0, Math.floor(r * (1 - amount)));
  g = Math.max(0, Math.floor(g * (1 - amount)));
  b = Math.max(0, Math.floor(b * (1 - amount)));
  return `rgb(${r}, ${g}, ${b})`;
};

/**
 * Pie3DChart — versi "3D pie" (bukan donut) dengan efek kedalaman (extrusion)
 * di sisi depan, supaya secara visual berbeda dari DonutChart standar.
 * Props sama persis dengan DonutChart agar mudah dipertukarkan.
 */
const Pie3DChart = ({ title, data, totalLabel = '(0 total)', frameless = false, className = '', depth = 20 }) => {
  const total = data.reduce((sum, item) => sum + item.value, 0);
  const chartData = data.map((item) => ({
    ...item,
    percentage: total > 0 ? Math.round((item.value / total) * 100) : 0,
  }));

  // Geometri elips (tampak pie dari sudut atas agak miring)
  const cx = 100;
  const rx = 88;
  const ry = 48;
  const cyTop = 66;

  const toRad = (deg) => ((deg - 90) * Math.PI) / 180;
  const pointAt = (angleDeg, cy) => {
    const rad = toRad(angleDeg);
    return { x: cx + rx * Math.cos(rad), y: cy + ry * Math.sin(rad) };
  };

  // Hitung batas sudut kumulatif tiap slice (0 = atas, searah jarum jam)
  let cum = 0;
  const slices = chartData.map((item) => {
    const startAngle = total > 0 ? (cum / total) * 360 : 0;
    cum += item.value;
    const endAngle = total > 0 ? (cum / total) * 360 : 0;
    return { ...item, startAngle, endAngle };
  });

  // Sisi depan pie (yang butuh "dinding" 3D) ada di rentang sudut 90°–270°
  const FRONT_START = 90;
  const FRONT_END = 270;
  const clipFront = (start, end) => {
    const s = Math.max(start, FRONT_START);
    const e = Math.min(end, FRONT_END);
    return s < e ? [s, e] : null;
  };

  const wallPaths = slices
    .map((sl, i) => {
      const seg = clipFront(sl.startAngle, sl.endAngle);
      if (!seg) return null;
      const [s, e] = seg;
      const p1 = pointAt(s, cyTop);
      const p2 = pointAt(e, cyTop);
      const p3 = pointAt(e, cyTop + depth);
      const p4 = pointAt(s, cyTop + depth);
      const largeArc = e - s > 180 ? 1 : 0;
      const d = `M ${p1.x} ${p1.y} A ${rx} ${ry} 0 ${largeArc} 1 ${p2.x} ${p2.y} L ${p3.x} ${p3.y} A ${rx} ${ry} 0 ${largeArc} 0 ${p4.x} ${p4.y} Z`;
      return { d, color: darkenColor(sl.color), key: `wall-${i}` };
    })
    .filter(Boolean);

  const topPaths = slices
    .map((sl, i) => {
      if (total <= 0) return null;
      const span = sl.endAngle - sl.startAngle;
      const isFull = span >= 359.99;
      let d;
      if (isFull) {
        const p1 = pointAt(0, cyTop);
        const p2 = pointAt(180, cyTop);
        d = `M ${p1.x} ${p1.y} A ${rx} ${ry} 0 1 1 ${p2.x} ${p2.y} A ${rx} ${ry} 0 1 1 ${p1.x} ${p1.y} Z`;
      } else {
        const p1 = pointAt(sl.startAngle, cyTop);
        const p2 = pointAt(sl.endAngle, cyTop);
        const largeArc = span > 180 ? 1 : 0;
        d = `M ${cx} ${cyTop} L ${p1.x} ${p1.y} A ${rx} ${ry} 0 ${largeArc} 1 ${p2.x} ${p2.y} Z`;
      }
      return { d, color: sl.color, key: `top-${i}` };
    })
    .filter(Boolean);

  const viewBoxHeight = cyTop + depth + ry + 12;

  const content = (
    // Breakpoint dinaikkan dari md ke xl — alasan sama seperti DonutChart.jsx
    // (chart ini ditaruh di grid 3 kolom, jadi harus tetap stack vertikal
    // di lebar iPad/tablet supaya tidak overflow).
    <div className="flex flex-col xl:flex-row items-center justify-center gap-8">
      <div className="flex items-center justify-center">
        <svg
          viewBox={`0 0 200 ${viewBoxHeight}`}
          className="w-56 h-44"
          style={{ overflow: 'visible' }}
        >
          {/* Dinding/sisi 3D (digambar dulu, di bawah permukaan atas) */}
          {wallPaths.map((w) => (
            <path key={w.key} d={w.d} fill={w.color} stroke={w.color} strokeWidth="0.5" />
          ))}
          {/* Permukaan atas pie — irisan warna asli */}
          {topPaths.map((t) => (
            <path key={t.key} d={t.d} fill={t.color} stroke="rgba(255,255,255,0.6)" strokeWidth="1" />
          ))}
        </svg>
      </div>

      <div className="flex-1 space-y-3">
        {chartData.map((item, index) => (
          <div key={index} className="flex items-center justify-between text-sm">
            <div className="flex items-center gap-2">
              <div
                className="w-3 h-3 rounded-full flex-shrink-0"
                style={{ backgroundColor: item.color }}
              />
              <span className="text-gray-700 dark:text-gray-300">{item.label}</span>
            </div>
            <span className="text-gray-500 dark:text-gray-400 font-medium whitespace-nowrap ml-2">
              ({item.value} - {item.percentage}%)
            </span>
          </div>
        ))}
      </div>
    </div>
  );

  if (frameless) {
    return (
      <div className={`space-y-4 ${className}`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-sm font-bold text-gray-900 dark:text-white">{title}</span>
            <span className="text-green-500 text-lg">✓</span>
          </div>
          <span className="text-xs text-gray-500 dark:text-gray-400">{totalLabel}</span>
        </div>
        {content}
      </div>
    );
  }

  return (
    <Card className={`hover:shadow-lg transition-shadow duration-200 ${className}`}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CardTitle className="text-sm font-bold text-gray-900 dark:text-white">
              {title}
            </CardTitle>
            <span className="text-green-500 text-lg">✓</span>
          </div>
          <span className="text-xs text-gray-500 dark:text-gray-400">{totalLabel}</span>
        </div>
      </CardHeader>
      <CardContent>
        {content}
      </CardContent>
    </Card>
  );
};

export default Pie3DChart;
