import { useEffect, useState } from "react";

import { API_BASE_URL } from '@/config/api';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";

export default function RekapKasbonPage() {
  const [overview, setOverview] = useState(null);
  const [perPegawai, setPerPegawai] = useState([]);
  const [pegawai, setPegawai] = useState([]);
  const [loading, setLoading] = useState(true);
  const { token, logout } = useAuth();

  // LOAD DATA
  const loadOverview = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/kasbon-summary/overview`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      setOverview(data);
    } catch (err) {
      console.error("Gagal load overview", err);
      toast.error("Gagal memuat overview kasbon");
    }
  };

  const loadPerPegawai = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/kasbon-summary/per-pegawai`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        setPerPegawai(data);
      }
    } catch (err) {
      console.error("Gagal load per pegawai", err);
    }
  };

  const loadPegawai = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/karyawan`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        // Filter hanya karyawan yang aktif
        const activePegawai = data.filter((k) => k.status === "active");
        setPegawai(activePegawai);
      }
    } catch (err) {
      console.error("Gagal load pegawai", err);
    }
  };

  useEffect(() => {
    loadOverview();
    loadPerPegawai();
    loadPegawai();
    setLoading(false);
  }, []);

  const formatRupiah = (val) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(val);
  };

  const getPegawaiName = (pegawaiId) => {
    return pegawai.find((p) => p.id === pegawaiId)?.nama_lengkap || "-";
  };

  if (loading) {
    return <div className="p-6">Loading...</div>;
  }

  return (
    <div className="p-6 space-y-6">
      {/* HEADER */}
      <div>
        <h1 className="text-3xl font-bold dark:text-gray-100">Rekap Kasbon</h1>
        <p className="text-sm text-gray-600 dark:text-gray-400">
          Ringkasan dan laporan kasbon pegawai
        </p>
      </div>

      {/* OVERVIEW CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-gray-600 dark:text-gray-400">
              Total Kasbon Diberikan
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{overview?.total_kasbon_count || 0}</div>
            <p className="text-xs text-gray-500 mt-1">
              {formatRupiah(overview?.total_kasbon_nominal || 0)}
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-yellow-600 dark:text-yellow-400">
              Belum Lunas
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-yellow-600 dark:text-yellow-400">
              {overview?.belum_lunas_count || 0}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              {formatRupiah(overview?.belum_lunas_nominal || 0)}
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-green-600 dark:text-green-400">
              Lunas
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600 dark:text-green-400">
              {overview?.lunas_count || 0}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              {formatRupiah(overview?.lunas_nominal || 0)}
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-blue-600 dark:text-blue-400">
              Persentase Lunas
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-blue-600 dark:text-blue-400">
              {overview?.total_kasbon_count > 0
                ? Math.round((overview.lunas_count / overview.total_kasbon_count) * 100)
                : 0}
              %
            </div>
            <p className="text-xs text-gray-500 mt-1">
              {overview?.lunas_count || 0} dari {overview?.total_kasbon_count || 0}
            </p>
          </CardContent>
        </Card>
      </div>

      {/* TABLE - PER PEGAWAI */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <div className="p-4 border-b dark:border-gray-700">
          <h2 className="font-semibold">Kasbon Per Pegawai</h2>
        </div>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Nama Pegawai</TableHead>
              <TableHead className="text-right">Total Kasbon</TableHead>
              <TableHead className="text-right">Total Sisa</TableHead>
              <TableHead className="text-right">Total Lunas</TableHead>
              <TableHead className="text-right">% Lunas</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {perPegawai.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} className="text-center text-gray-500">
                  Tidak ada data kasbon
                </TableCell>
              </TableRow>
            ) : (
              perPegawai.map((item) => {
                const persentaseLunas =
                  item.total_kasbon > 0
                    ? Math.round(((item.total_kasbon - item.total_sisa) / item.total_kasbon) * 100)
                    : 0;

                return (
                  <TableRow key={item.pegawai_id}>
                    <TableCell className="font-medium">
                      {getPegawaiName(item.pegawai_id)}
                    </TableCell>
                    <TableCell className="text-right">
                      {formatRupiah(item.total_kasbon)}
                    </TableCell>
                    <TableCell className="text-right text-orange-600 dark:text-orange-400 font-medium">
                      {formatRupiah(item.total_sisa)}
                    </TableCell>
                    <TableCell className="text-right text-green-600 dark:text-green-400 font-medium">
                      {formatRupiah(item.total_kasbon - item.total_sisa)}
                    </TableCell>
                    <TableCell className="text-right">
                      <span
                        className={`px-2 py-1 rounded text-xs font-semibold ${
                          persentaseLunas === 100
                            ? "bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300"
                            : persentaseLunas > 50
                            ? "bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300"
                            : "bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-300"
                        }`}
                      >
                        {persentaseLunas}%
                      </span>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      {/* DETAIL PER PEGAWAI */}
      <div className="space-y-4">
        {perPegawai.length > 0 && (
          <>
            <h2 className="font-semibold text-lg">Detail Kasbon Per Pegawai</h2>
            {perPegawai.map((pegawaiData) => (
              <Card key={pegawaiData.pegawai_id}>
                <CardHeader>
                  <CardTitle>{getPegawaiName(pegawaiData.pegawai_id)}</CardTitle>
                  <CardDescription>
                    Total Kasbon: {formatRupiah(pegawaiData.total_kasbon)} | Sisa:{" "}
                    {formatRupiah(pegawaiData.total_sisa)}
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="border-b">
                        <tr>
                          <th className="text-left py-2">Nominal</th>
                          <th className="text-right py-2">Sisa</th>
                          <th className="text-left py-2">Status</th>
                          <th className="text-left py-2">Tanggal</th>
                        </tr>
                      </thead>
                      <tbody>
                        {pegawaiData.kasbon_items.map((kasbon) => (
                          <tr key={kasbon.id} className="border-b">
                            <td className="py-2">{formatRupiah(kasbon.nominal)}</td>
                            <td className="text-right">{formatRupiah(kasbon.sisa)}</td>
                            <td>
                              <span
                                className={`px-2 py-1 rounded text-xs font-semibold ${
                                  kasbon.status === "Lunas"
                                    ? "bg-green-100 text-green-700"
                                    : "bg-yellow-100 text-yellow-700"
                                }`}
                              >
                                {kasbon.status}
                              </span>
                            </td>
                            <td>
                              {kasbon.tanggal
                                ? new Date(kasbon.tanggal).toLocaleDateString("id-ID")
                                : "-"}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </CardContent>
              </Card>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
