import React, { useState } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { useAppSettings } from '../contexts/AppSettingsContext';
import { Megaphone, AlertTriangle, Siren, PartyPopper, X } from 'lucide-react';

// Notifikasi vendor ditujukan untuk dashboard pengurus RT/RW/Kelurahan,
// dan sekarang juga ditampilkan untuk sisi Warga.
const ADMIN_ROLES = ['admin', 'pengurus_rw', 'pengurus_kelurahan', 'warga'];

const TIPE_STYLE = {
  info:     { bg: 'bg-sky-600',    icon: Megaphone },
  penting:  { bg: 'bg-amber-600',  icon: AlertTriangle },
  darurat:  { bg: 'bg-red-600',    icon: Siren },
  kegiatan: { bg: 'bg-emerald-600', icon: PartyPopper },
};

export default function VendorAnnouncementBanner() {
  const { user } = useAuth();
  const { notifikasiAktif } = useAppSettings();
  const [dismissedId, setDismissedId] = useState(null);

  if (!ADMIN_ROLES.includes(user?.role)) return null;
  if (!notifikasiAktif) return null;
  if (dismissedId === notifikasiAktif.id) return null;

  const { bg, icon: Icon } = TIPE_STYLE[notifikasiAktif.tipe] || TIPE_STYLE.info;

  return (
    <div className={`w-full flex items-start gap-2 px-4 py-2 ${bg} text-white text-sm`}>
      <Icon size={16} className="flex-shrink-0 mt-0.5" />
      <div className="flex-1 min-w-0 leading-snug">
        <span className="font-semibold">{notifikasiAktif.judul}</span>
        <span className="ml-1 opacity-95">— {notifikasiAktif.isi}</span>
      </div>
      <button
        onClick={() => setDismissedId(notifikasiAktif.id)}
        className="p-1 rounded hover:bg-white/20 flex-shrink-0"
        aria-label="Tutup pengumuman"
      >
        <X size={14} />
      </button>
    </div>
  );
}
