import React, { useState } from 'react'
import { useCMS } from './cmsContent.jsx'
import { useAppSettings } from '../../contexts/AppSettingsContext'

export default function FAQ() {
  const c = useCMS('faq')
  const { supportWhatsapp } = useAppSettings()
  const items = c.items || []
  const [open, setOpen] = useState(0)
  // Placeholder "__SUPPORT_WA__" ditulis di konten CMS (backend/cms.py) —
  // ditukar di sini dengan link wa.me nomor support default vendor
  // (Vendor > Settings > No. WhatsApp Support Default).
  const descriptionHtml = (c.description_html || '').replace(
    '__SUPPORT_WA__',
    supportWhatsapp ? `https://wa.me/${supportWhatsapp}` : '#'
  )
  return (
    <section className="section" id="faq" style={{paddingTop: 60}}>
      <div className="container">
        <div className="faq-wrap">
          <div>
            <span className="kicker">{c.kicker}</span>
            <h2 style={{fontFamily:"'Instrument Serif', serif", fontSize:'clamp(36px, 5vw, 60px)', fontWeight:400, lineHeight:1.02, letterSpacing:'-0.02em', marginTop:18, textWrap:'balance'}}
              dangerouslySetInnerHTML={{ __html: c.title_html }} />
            <p style={{marginTop:18, color:'var(--ink-soft)', fontSize:15}}
              dangerouslySetInnerHTML={{ __html: descriptionHtml }} />
          </div>
          <div>
            {items.map((it, i) => (
              <div key={i} className={'faq-item ' + (open===i ? 'open' : '')} onClick={() => setOpen(open===i ? -1 : i)}>
                <div className="faq-q">
                  <span>{it.question}</span>
                  <span className="ico">+</span>
                </div>
                <div className="faq-a">{it.answer}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  )
}
