import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '@/config/api';
import { toast } from '@/components/ui/sonner';
import { LayoutTemplate, Globe, Loader2 } from 'lucide-react';

const token = () => localStorage.getItem('vendor_token');
const hdrs  = () => ({ Authorization: `Bearer ${token()}` });

// Ilustrasi mini per tema login — murni visual (bukan preview live) supaya
// vendor punya gambaran tata letaknya tanpa perlu buka halaman login asli.
function LayoutPreview({ id }) {
  if (id === 'split-center') {
    return (
      <div className="w-full h-20 rounded-lg overflow-hidden flex border border-gray-200">
        <div className="w-1/2 bg-[#ed6f5c] flex items-center justify-center">
          <div className="w-5 h-5 rounded bg-white/80" />
        </div>
        <div className="w-1/2 bg-white flex flex-col items-center justify-center gap-1">
          <div className="w-10 h-1.5 rounded bg-gray-300" />
          <div className="w-10 h-1.5 rounded bg-gray-200" />
        </div>
      </div>
    );
  }
  if (id === 'elegant') {
    return (
      <div className="w-full h-20 rounded-lg overflow-hidden relative bg-gradient-to-br from-[#ed6f5c] via-[#7c3a2e] to-black flex items-center justify-center">
        <div className="w-16 h-14 rounded-lg bg-white/15 border border-white/30 backdrop-blur flex flex-col items-center justify-center gap-1">
          <div className="w-4 h-4 rounded bg-white/70" />
          <div className="w-8 h-1 rounded bg-white/50 mt-1" />
        </div>
      </div>
    );
  }
  // default (diagonal)
  return (
    <div className="w-full h-20 rounded-lg overflow-hidden flex border border-gray-200">
      <div className="w-[58%] bg-[#ed6f5c] flex items-center justify-center relative">
        <div className="w-5 h-5 rounded bg-white/80" />
      </div>
      <div className="flex-1 bg-white flex flex-col items-center justify-center gap-1">
        <div className="w-10 h-1.5 rounded bg-gray-300" />
        <div className="w-10 h-1.5 rounded bg-gray-200" />
      </div>
    </div>
  );
}

export default function VendorLoginLayoutSettings() {
  const [data, setData] = useState(null); // { presets, published_ids }
  const [loading, setLoading] = useState(true);
  const [publishing, setPublishing] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/login-layout-settings`, { headers: hdrs() });
      const json = await res.json();
      if (!res.ok) throw new Error(json.detail || 'Gagal memuat tema login');
      setData(json);
    } catch (e) {
      toast.error(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const togglePublish = async (layout) => {
    if (publishing) return;
    const isDefault = layout.id === 'default';
    if (isDefault) return;
    const nextPublished = !(data.published_ids || []).includes(layout.id);
    setPublishing(layout.id);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/login-layout-settings/publish`, {
        method: 'PUT',
        headers: { ...hdrs(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ layout_id: layout.id, published: nextPublished }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.detail || 'Gagal mengubah status publish');
      setData(d => ({ ...d, published_ids: json.published_ids }));
      toast.success(
        nextPublished
          ? `Tema login "${layout.name}" dipublish — bisa dipilih Kelurahan di semua slug`
          : `Tema login "${layout.name}" tidak lagi dipublish`
      );
    } catch (e) {
      toast.error(e.message);
    } finally {
      setPublishing(null);
    }
  };

  if (loading) {
    return (
      <div className="lg:col-span-3 bg-white rounded-xl border border-gray-200 p-5 flex justify-center py-16">
        <Loader2 size={24} className="animate-spin text-gray-400" />
      </div>
    );
  }
  if (!data) return null;

  return (
    <div className="lg:col-span-3 bg-white rounded-xl border border-gray-200 p-5 space-y-4">
      <div>
        <h2 className="text-sm font-semibold text-gray-800 flex items-center gap-2">
          <LayoutTemplate size={15} className="text-[#ed6f5c]" /> Tema Login
        </h2>
        <p className="text-xs text-gray-400 mt-0.5">
          Pilihan TATA LETAK halaman login ber-slug Kelurahan (beda dari Tema Warna di atas). "Default" selalu
          tersedia; publish tema lain supaya bisa dipilih Kelurahan di menu Konfigurasi &gt; Setting.
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        {data.presets.map(layout => {
          const isDefault = layout.id === 'default';
          const isPublished = isDefault || (data.published_ids || []).includes(layout.id);
          const isBusy = publishing === layout.id;
          return (
            <div key={layout.id} className="rounded-xl border-2 border-gray-200 p-3">
              <LayoutPreview id={layout.id} />
              <p className="text-xs font-semibold text-gray-800 mt-2.5">{layout.name}</p>
              <p className="text-[11px] text-gray-400 mt-1 leading-snug">{layout.description}</p>
              <button
                onClick={() => togglePublish(layout)}
                disabled={isDefault || isBusy}
                title={isDefault ? 'Tema default selalu tersedia untuk semua Kelurahan' : 'Publish supaya bisa dipilih Kelurahan di menu Konfigurasi > Setting'}
                className={`w-full mt-3 flex items-center justify-center gap-1.5 py-1.5 rounded-lg text-[11px] font-semibold border transition-colors ${
                  isDefault
                    ? 'bg-gray-50 text-gray-400 border-gray-200 cursor-default'
                    : isPublished
                    ? 'bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100'
                    : 'bg-white text-gray-500 border-gray-200 hover:bg-gray-50'
                }`}
              >
                <Globe size={11} />
                {isBusy ? 'Memproses...' : isDefault ? 'Selalu tersedia' : isPublished ? 'Dipublish ke semua slug' : 'Publish ke semua slug'}
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}
