// ─── HELPERS ──────────────────────────────────────────────────────────────────
function schemaToRow(f) {
  return {
    id: f.id || '',
    label: f.label || '',
    type: f.type || 'text',
    required: !!f.required,
    optionsStr: Array.isArray(f.options) ? f.options.join(', ') : '',
  };
}
function rowToSchema(r) {
  const s = { id: r.id, label: r.label, type: r.type, required: r.required };
  if (r.type === 'select') s.options = r.optionsStr.split(',').map(v => v.trim()).filter(Boolean);
  return s;
}
function extractBody(html) {
  if (!html) return '';
  if (!html.includes('<body')) return html;
  const m = html.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  return m ? m[1].trim() : html;
}

// ─── FIELD BUILDER ────────────────────────────────────────────────────────────
function FieldBuilder({ fieldsJson, onChange }) {
  const [rows, setRows] = useState(() => {
    try {
      const p = JSON.parse(fieldsJson || '[]');
      return Array.isArray(p) ? p.map(schemaToRow) : [];
    } catch { return []; }
  });
  const [parseError] = useState(() => {
    try { const p = JSON.parse(fieldsJson || '[]'); return !Array.isArray(p); }
    catch { return true; }
  });
  const [rawFallback, setRawFallback] = useState(fieldsJson || '[]');

  const syncUp = (newRows) => {
    setRows(newRows);
    onChange(JSON.stringify(newRows.map(rowToSchema)));
  };

  const updateRow = (i, key, val) => {
    const next = rows.map((r, idx) => idx === i ? { ...r, [key]: val } : r);
    syncUp(next);
  };

  const deleteRow = (i) => syncUp(rows.filter((_, idx) => idx !== i));

  const addRow = () => syncUp([...rows, { id: '', label: '', type: 'text', required: false, optionsStr: '' }]);

  if (parseError) {
    return (
      <div className="space-y-3">
        <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600">
          <AlertTriangle size={14} /> Format JSON tidak valid — mengedit dalam mode raw
        </div>
        <textarea value={rawFallback} onChange={e => { setRawFallback(e.target.value); onChange(e.target.value); }}
          rows={10} className="w-full border border-gray-200 rounded-xl px-3 py-2 text-xs font-mono focus:outline-none focus:ring-2 focus:ring-orange-400 resize-none" />
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between mb-3">
        <div>
          <p className="text-sm font-semibold text-gray-700">Form Fields</p>
          <p className="text-xs text-gray-400">Field yang harus diisi pemohon saat mengajukan surat</p>
        </div>
        <span className="text-xs bg-orange-100 text-orange-700 px-2 py-1 rounded-full font-medium">{rows.length} field</span>
      </div>

      {rows.length === 0 && (
        <div className="text-center py-8 text-gray-400 border-2 border-dashed border-gray-200 rounded-xl">
          <p className="text-sm">Belum ada field</p>
          <p className="text-xs mt-1">Klik "+ Tambah Field" untuk menambahkan</p>
        </div>
      )}

      {rows.map((r, i) => (
        <div key={i} className="p-3 bg-white border border-gray-200 rounded-xl space-y-2 hover:border-orange-200 transition-colors">
          <div className="flex items-center gap-2 flex-wrap">
            <input value={r.id} onChange={e => updateRow(i, 'id', e.target.value)}
              placeholder="field_id"
              className="w-28 border border-gray-200 rounded-lg px-2 py-1.5 text-xs font-mono focus:outline-none focus:ring-1 focus:ring-orange-400" />
            <input value={r.label} onChange={e => updateRow(i, 'label', e.target.value)}
              placeholder="Label Field"
              className="flex-1 min-w-[120px] border border-gray-200 rounded-lg px-2 py-1.5 text-xs focus:outline-none focus:ring-1 focus:ring-orange-400" />
            <select value={r.type} onChange={e => updateRow(i, 'type', e.target.value)}
              className="w-24 border border-gray-200 rounded-lg px-2 py-1.5 text-xs focus:outline-none focus:ring-1 focus:ring-orange-400">
              <option value="text">Teks</option>
              <option value="textarea">Paragraf</option>
              <option value="date">Tanggal</option>
              <option value="number">Angka</option>
              <option value="select">Pilihan</option>
            </select>
            <button onClick={() => updateRow(i, 'required', !r.required)}
              className={`px-2 py-1.5 text-xs rounded-lg border whitespace-nowrap transition-colors ${r.required ? 'bg-green-50 border-green-300 text-green-700' : 'bg-gray-50 border-gray-200 text-gray-400 hover:border-gray-300'}`}>
              {r.required ? '✓ Wajib' : 'Opsional'}
            </button>
            <button onClick={() => deleteRow(i)} className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors">
              <Trash2 size={13} />
            </button>
          </div>
          {r.type === 'select' && (
            <input value={r.optionsStr} onChange={e => updateRow(i, 'optionsStr', e.target.value)}
              placeholder="Opsi A, Opsi B, Opsi C  (pisahkan dengan koma)"
              className="w-full border border-orange-200 bg-orange-50/40 rounded-lg px-2 py-1.5 text-xs focus:outline-none focus:ring-1 focus:ring-orange-400" />
          )}
        </div>
      ))}

      <button onClick={addRow}
        className="w-full border-2 border-dashed border-gray-200 rounded-xl py-2.5 text-sm text-gray-500 hover:border-orange-300 hover:text-orange-600 hover:bg-orange-50/30 transition-colors flex items-center justify-center gap-1.5">
        <Plus size={14} /> Tambah Field
      </button>
    </div>
  );
}

