import React, { useCallback, useEffect, useState } from 'react';
import { AlertTriangle, ChevronLeft, ChevronRight, RefreshCw } from 'lucide-react';
import { API_ENDPOINTS } from '../../config/api';

const PAGE_SIZE = 100;

const LEVEL_STYLES = {
  ERROR: 'bg-red-100 text-red-700',
  WARNING: 'bg-amber-100 text-amber-700',
  INFO: 'bg-blue-100 text-blue-700',
};

export default function VendorSystemLogs() {
  const [items, setItems] = useState([]);
  const [level, setLevel] = useState('');
  const [offset, setOffset] = useState(0);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const fetchLogs = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({
        limit: String(PAGE_SIZE),
        offset: String(offset),
      });
      if (level) params.set('level', level);

      const token = localStorage.getItem('vendor_token');
      const response = await fetch(`${API_ENDPOINTS.VENDOR_SYSTEM_LOGS}?${params}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.detail || `HTTP ${response.status}`);
      }
      setItems(data.items);
      setTotal(data.total);
    } catch (fetchError) {
      setError(fetchError.message || 'Gagal memuat system logs');
    } finally {
      setLoading(false);
    }
  }, [level, offset]);

  useEffect(() => {
    fetchLogs();
  }, [fetchLogs]);

  const handleLevelChange = (event) => {
    setLevel(event.target.value);
    setOffset(0);
  };

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">System Logs</h1>
          <p className="mt-1 text-sm text-gray-500">
            Log backend INFO, WARNING, dan ERROR. Total {total.toLocaleString('id-ID')} entri.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <select
            value={level}
            onChange={handleLevelChange}
            className="rounded-xl border border-gray-200 bg-white px-3 py-2 text-sm text-gray-700"
            aria-label="Filter level log"
          >
            <option value="">Semua level</option>
            <option value="ERROR">Error</option>
            <option value="WARNING">Warning</option>
            <option value="INFO">Info</option>
          </select>
          <button
            type="button"
            onClick={fetchLogs}
            disabled={loading}
            className="flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-3 py-2 text-sm hover:bg-gray-50 disabled:opacity-60"
          >
            <RefreshCw size={15} className={loading ? 'animate-spin' : ''} />
            Refresh
          </button>
        </div>
      </div>

      {error && (
        <div role="alert" className="flex items-center gap-2 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">
          <AlertTriangle size={17} />
          {error}
        </div>
      )}

      <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white">
        {loading && items.length === 0 ? (
          <div className="py-16 text-center text-sm text-gray-500">Memuat system logs...</div>
        ) : items.length === 0 ? (
          <div className="py-16 text-center text-sm text-gray-500">
            {error ? 'Log tidak dapat dimuat.' : 'Belum ada log untuk filter ini.'}
          </div>
        ) : (
          <div className="divide-y divide-gray-100">
            {items.map((entry) => (
              <article key={entry.id} className="space-y-2 p-4">
                <div className="flex flex-wrap items-center gap-2">
                  <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${LEVEL_STYLES[entry.level] || 'bg-gray-100 text-gray-700'}`}>
                    {entry.level}
                  </span>
                  <time className="text-xs text-gray-500">
                    {new Date(entry.timestamp).toLocaleString('id-ID')}
                  </time>
                  <span className="text-xs text-gray-400">{entry.logger_name}</span>
                </div>
                <p className="whitespace-pre-wrap break-words text-sm text-gray-800">{entry.message}</p>
                {entry.exception && (
                  <details className="text-xs text-gray-500">
                    <summary className="cursor-pointer font-medium">Detail exception</summary>
                    <pre className="mt-2 max-h-72 overflow-auto whitespace-pre-wrap break-words rounded-lg bg-gray-50 p-3">
                      {entry.exception}
                    </pre>
                  </details>
                )}
              </article>
            ))}
          </div>
        )}

        <div className="flex items-center justify-between border-t border-gray-100 px-4 py-3">
          <span className="text-xs text-gray-500">
            {total === 0 ? '0 log' : `${offset + 1}–${Math.min(offset + items.length, total)} dari ${total}`}
          </span>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => setOffset((current) => Math.max(0, current - PAGE_SIZE))}
              disabled={offset === 0 || loading}
              className="rounded-lg border border-gray-200 p-2 text-gray-600 hover:bg-gray-50 disabled:opacity-40"
              aria-label="Halaman sebelumnya"
            >
              <ChevronLeft size={16} />
            </button>
            <button
              type="button"
              onClick={() => setOffset((current) => current + PAGE_SIZE)}
              disabled={offset + PAGE_SIZE >= total || loading}
              className="rounded-lg border border-gray-200 p-2 text-gray-600 hover:bg-gray-50 disabled:opacity-40"
              aria-label="Halaman berikutnya"
            >
              <ChevronRight size={16} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
