const CMSContext = createContext(DEFAULT_CONTENT);

export function CMSProvider({ children }) {
  const [content, setContent] = useState(DEFAULT_CONTENT);

  useEffect(() => {
    let cancelled = false;
    fetch(`${API_BASE_URL}/api/cms/landing`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error('HTTP ' + r.status))))
      .then((data) => {
        if (cancelled) return;
        if (data && typeof data === 'object') {
          const merged = { ...DEFAULT_CONTENT };
          Object.keys(data).forEach((k) => {
            if (k in DEFAULT_CONTENT) merged[k] = data[k];
          });
          setContent(merged);
        }
      })
      .catch(() => { /* keep defaults silently */ });
    return () => { cancelled = true; };
  }, []);

  return <CMSContext.Provider value={content}>{children}</CMSContext.Provider>;
}

// Konten CMS lama (disimpan sebelum landing3 ada) masih menyebut "Ruang
// Warga" di beberapa teks bebas (subtitle, deskripsi modul, pertanyaan FAQ,
// footer, dst). Daripada mengedit satu-satu tiap file komponen, teks itu
// diganti otomatis ke nama aplikasi vendor di sini, terpusat, jadi berlaku
// untuk section manapun tanpa perlu ubah kode lagi kalau CMS diedit ulang.
function deepSwapBrand(value, appName) {
  if (typeof value === 'string') {
    return /ruang warga/i.test(value) ? value.replace(/ruang warga/gi, appName) : value;
  }
  if (Array.isArray(value)) {
    return value.map((v) => deepSwapBrand(v, appName));
  }
  if (value && typeof value === 'object') {
    const out = {};
    Object.keys(value).forEach((k) => { out[k] = deepSwapBrand(value[k], appName); });
    return out;
  }
  return value;
}

// useCMS('hero') returns merged section data (defaults overridden by saved)
export function useCMS(section) {
  const content = useContext(CMSContext);
  const { appName } = useAppSettings();
  const fallback = DEFAULT_CONTENT[section] || {};
  const value = content[section] || {};
  return deepSwapBrand({ ...fallback, ...value }, appName || 'Merata Digital');
}
