import React, { useState, useRef } from 'react';
import EmojiPicker from 'emoji-picker-react';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Smile, Bold, Italic, Link as LinkIcon } from 'lucide-react';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from './ui/popover';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from './ui/dialog';

const MessageEditor = ({ value, onChange, placeholder = 'Tulis pesan Anda...', rows = 5, disabled = false }) => {
  const [showEmoji, setShowEmoji] = useState(false);
  const [showLinkDialog, setShowLinkDialog] = useState(false);
  const [linkInput, setLinkInput] = useState('');
  const textareaRef = useRef(null);

  const insertText = (text, wrapStart = '', wrapEnd = '') => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = value.substring(start, end);
    
    const before = value.substring(0, start);
    const after = value.substring(end);
    
    let newText;
    let newCursorPos;

    if (selectedText) {
      // Ada text yang diselect
      newText = `${before}${wrapStart}${selectedText}${wrapEnd}${after}`;
      newCursorPos = start + wrapStart.length + selectedText.length + wrapEnd.length;
    } else {
      // Tidak ada text yang diselect
      newText = `${before}${text}${after}`;
      newCursorPos = start + text.length;
    }

    onChange(newText);

    // Set cursor position setelah update
    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(newCursorPos, newCursorPos);
    }, 0);
  };

  const handleBold = () => {
    insertText('**teks tebal**', '*', '*');
  };

  const handleItalic = () => {
    insertText('_teks miring_', '_', '_');
  };

  const linkSelectionRef = useRef({ start: 0, end: 0 });

  const handleLink = () => {
    const textarea = textareaRef.current;
    // Simpan posisi cursor/seleksi SEBELUM dialog dibuka — begitu dialog
    // muncul, textarea kehilangan fokus jadi textarea.selectionStart/End
    // tidak bisa diandalkan lagi saat tombol "Sisipkan" diklik nanti.
    if (textarea) {
      linkSelectionRef.current = { start: textarea.selectionStart, end: textarea.selectionEnd };
    }
    setLinkInput('');
    setShowLinkDialog(true);
  };

  const handleInsertLink = () => {
    const url = linkInput.trim();
    if (!url) { setShowLinkDialog(false); return; }

    const { start, end } = linkSelectionRef.current;
    const before = value.substring(0, start);
    const after = value.substring(end);
    const newText = `${before}${url}${after}`;
    const newCursorPos = start + url.length;

    onChange(newText);
    setShowLinkDialog(false);

    setTimeout(() => {
      const textarea = textareaRef.current;
      if (textarea) {
        textarea.focus();
        textarea.setSelectionRange(newCursorPos, newCursorPos);
      }
    }, 0);
  };

  const handleEmojiClick = (emojiData) => {
    insertText(emojiData.emoji);
    setShowEmoji(false);
  };

  return (
    <div className="space-y-2">
      <div className="flex gap-2 items-center border-b pb-2">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={handleBold}
          disabled={disabled}
          title="Bold (WhatsApp: *text*)"
        >
          <Bold className="h-4 w-4" />
        </Button>
        
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={handleItalic}
          disabled={disabled}
          title="Italic (WhatsApp: _text_)"
        >
          <Italic className="h-4 w-4" />
        </Button>
        
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={handleLink}
          disabled={disabled}
          title="Insert Link"
        >
          <LinkIcon className="h-4 w-4" />
        </Button>

        <div className="ml-auto">
          <Popover open={showEmoji} onOpenChange={setShowEmoji}>
            <PopoverTrigger asChild>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                disabled={disabled}
                title="Emoji"
              >
                <Smile className="h-4 w-4" />
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-full p-0 border-0" align="end">
              <EmojiPicker
                onEmojiClick={handleEmojiClick}
                width={320}
                height={400}
                searchPlaceholder="Cari emoji..."
                previewConfig={{ showPreview: false }}
              />
            </PopoverContent>
          </Popover>
        </div>
      </div>

      <textarea
        ref={textareaRef}
        className="w-full p-3 text-sm border rounded-md focus:outline-none focus:ring-2 focus:ring-cyan-500 dark:bg-gray-900 dark:border-gray-700 dark:text-gray-100"
        placeholder={placeholder}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        rows={rows}
        disabled={disabled}
      />

      <div className="flex justify-between text-xs text-gray-500">
        <div className="space-x-3">
          <span>Format WhatsApp: *bold* _italic_ ~strikethrough~</span>
        </div>
        <span>{value?.length || 0} karakter</span>
      </div>

      {/* Dialog custom bergaya aplikasi — menggantikan window.prompt() bawaan
          browser yang tampilannya beda sendiri ("ruangwarga.vercel.app says...") */}
      <Dialog open={showLinkDialog} onOpenChange={setShowLinkDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Sisipkan Link</DialogTitle>
          </DialogHeader>
          <div className="py-2">
            <label className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5 block">
              URL
            </label>
            <Input
              autoFocus
              placeholder="https://..."
              value={linkInput}
              onChange={(e) => setLinkInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') { e.preventDefault(); handleInsertLink(); }
              }}
            />
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setShowLinkDialog(false)}>
              Batal
            </Button>
            <Button type="button" onClick={handleInsertLink}>
              Sisipkan
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default MessageEditor;
