// Ingat slug kelurahan tempat user terakhir login (mis. "giriawas") supaya
// logout / sesi habis / 401 selalu kembali ke halaman login ber-slug yang
// sama (/{slug}/login), bukan ke /login generik.
const KEY = 'tenant_slug';

export const getStoredTenantSlug = () => localStorage.getItem(KEY) || null;

export const setStoredTenantSlug = (slug) => {
  if (slug) localStorage.setItem(KEY, slug);
  else localStorage.removeItem(KEY);
};

export const getLoginPath = () => {
  const slug = getStoredTenantSlug();
  return slug ? `/${slug}/login` : '/login';
};
