// Panduan visual per menu untuk WARGA (terutama lansia): bahasa sederhana,
// langkah singkat. Tiap halaman punya panduan sendiri yang muncul otomatis
// saat menu itu pertama kali dibuka, dan bisa dibuka lagi lewat tombol
// "Panduan" di pojok kanan atas.
//
// target step (opsional) — elemen yang disorot:
//   'css selector'                         → document.querySelector
//   { sel: 'button, a', text: /regex/i }   → elemen pertama yang teksnya cocok
// Kalau elemen tidak ditemukan, kartu petunjuk tampil di tengah layar.

const TITLE = { sel: 'main h1' };
const HELP_BTN = '[data-tour="help-btn"]';

const closing = {
  title: 'Lupa caranya? Tenang.',
  body: 'Tekan tombol "Panduan" di pojok kanan atas kapan saja untuk melihat petunjuk halaman ini lagi.',
  target: HELP_BTN,
};

// Panduan sederhana: judul halaman → (opsional) tombol utama → (opsional) daftar → penutup
function simple({ id, path, nama, fungsi, aksi, aksiBody, daftar, daftarBody }) {
  const steps = [
    { title: `Halaman ${nama}`, body: fungsi, target: TITLE },
  ];
  if (aksi) steps.push({ title: aksiBody.title, body: aksiBody.body, target: { sel: 'main button, main a', text: aksi } });
  if (daftar) steps.push({ title: daftarBody.title, body: daftarBody.body, target: daftar });
  steps.push(closing);
  return { id, path, steps };
}

