// Cari panduan untuk sebuah alamat halaman:
//  1) cocok persis, 2) cocok awalan (mis. /ipl/tagihan → panduan /ipl), 3) null.
export function findWargaTour(pathname) {
  const p = (pathname || '/').replace(/\/+$/, '') || '/';
  const exact = WARGA_TOURS.find((t) => t.path === p);
  if (exact) return exact;
  const byPrefix = WARGA_TOURS
    .filter((t) => t.path !== '/' && p.startsWith(`${t.path}/`))
    .sort((a, b) => b.path.length - a.path.length)[0];
  return byPrefix || null;
}

// Panduan otomatis untuk menu/halaman APA PUN yang belum punya panduan khusus,
// supaya SEMUA menu tetap memunculkan petunjuk saat pertama kali dibuka.
export function buildGenericTour(pathname, nama) {
  const p = (pathname || '/').replace(/\/+$/, '') || '/';
  const label = (nama || '').trim() || 'ini';
  return {
    id: `auto:${p}`,
    path: p,
    steps: [
      {
        title: `Halaman ${label}`,
        body: `Anda sedang berada di menu "${label}". Gulir (geser) layar ke bawah untuk melihat seluruh isi halaman. Tekan tombol atau tulisan berwarna untuk membuka rinciannya.`,
        target: TITLE,
      },
      {
        title: 'Butuh bantuan?',
        body: 'Untuk pindah ke menu lain, gunakan daftar menu ini. Di HP, buka dengan menekan ikon garis tiga di pojok kiri atas.',
        target: 'aside',
        sidebar: true,
      },
      closing,
    ],
  };
}
