import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Edit, Wallet, CheckCircle, RefreshCw, Trash2 } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
    AlertDialogTrigger,
} from '@/components/ui/alert-dialog';

const formatRp = (val) => `Rp ${Number(val || 0).toLocaleString('id-ID', { maximumFractionDigits: 0 })}`;

export default function ThrBudgetList({ data, onEdit, onPay, onDelete, onRefresh, onCancelPay }) {
    const [isRefreshing, setIsRefreshing] = useState(false);

    // Manual refresh
    const handleManualRefresh = async () => {
        setIsRefreshing(true);
        if (onRefresh) {
            await onRefresh();
        }
        setIsRefreshing(false);
    };

    // Calculate summary stats
    const totalTarget = data.reduce((sum, item) => sum + (item.total_thr || 0), 0);
    const totalAccumulatedRaw = data.reduce((sum, item) => sum + (item.accumulated_amount || 0), 0);
    // Cap displayed value ke target (max 100%)
    const totalAccumulated = Math.min(totalAccumulatedRaw, totalTarget);
    const monthlyTarget = totalTarget > 0 ? Math.round(totalTarget / 12) : 0;
    const totalRumah = 37; // Total rumah di database
    const monthlyPerHouse = monthlyTarget > 0 ? Math.round(monthlyTarget / totalRumah) : 0;

    const getStatusColor = (status) => {
        switch (status) {
            case 'PAID': return 'bg-gray-100 text-gray-800 border-gray-300';
            case 'SIAP BAYAR': return 'bg-blue-100 text-blue-800 border-blue-200';
            case 'AMAN': return 'bg-green-100 text-green-800 border-green-200';
            case 'KURANG': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
            default: return 'bg-gray-100 text-gray-500';
        }
    };

    const getProgressColor = (status) => {
        if (status === 'PAID') return 'bg-gray-400';
        if (status === 'SIAP BAYAR') return 'bg-[var(--rw-primary)]';
        if (status === 'AMAN') return 'bg-green-500';
        return 'bg-amber-400';
    };

    return (
        <div>
            {/* Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
                {/* Card 1: Total Target THR */}
                <Card className="border-l-4 border-l-amber-500 shadow-sm">
                    <CardContent className="p-6">
                        <p className="text-sm text-gray-600 dark:text-gray-400 font-medium mb-2">Total Target THR</p>
                        <p className="text-2xl font-bold text-amber-600 dark:text-amber-400 mb-1">{formatRp(totalTarget)}</p>
                        <p className="text-xs text-gray-500">{data.length} dari {data.length} item aktif</p>
                    </CardContent>
                </Card>

                {/* Card 2: Target THR per Bulan */}
                <Card className="border-l-4 border-l-blue-500 shadow-sm">
                    <CardContent className="p-6">
                        <p className="text-sm text-gray-600 dark:text-gray-400 font-medium mb-2">Target THR per Bulan</p>
                        <p className="text-2xl font-bold text-blue-600 dark:text-blue-400 mb-1">{formatRp(monthlyTarget)}</p>
                        <p className="text-xs text-gray-500">Total target dibagi 12 bulan</p>
                    </CardContent>
                </Card>

                {/* Card 3: Iuran THR per Rumah/Bulan */}
                <Card className="border-l-4 border-l-teal-500 shadow-sm">
                    <CardContent className="p-6">
                        <p className="text-sm text-gray-600 dark:text-gray-400 font-medium mb-2">Iuran THR per Rumah/Bulan</p>
                        <p className="text-2xl font-bold text-teal-600 dark:text-teal-400 mb-1">{formatRp(monthlyPerHouse)}</p>
                        <p className="text-xs text-gray-500">Target bulanan dibagi jumlah rumah</p>
                    </CardContent>
                </Card>

                {/* Card 4: Total Iuran THR Terkumpul */}
                <Card className="border-l-4 border-l-green-500 shadow-sm">
                    <CardContent className="p-6">
                        <p className="text-sm text-gray-600 dark:text-gray-400 font-medium mb-2">Total Iuran THR Terkumpul</p>
                        <p className="text-2xl font-bold text-green-600 dark:text-green-400 mb-1">{formatRp(totalAccumulated)}</p>
                        <p className="text-xs text-gray-500">Status: {totalTarget > 0 ? ((totalAccumulated / totalTarget) * 100).toFixed(2) : 0}%</p>
                    </CardContent>
                </Card>
            </div>

            {/* Table */}
            <div className="overflow-x-auto rounded-md border shadow-sm mt-4">
                <table className="w-full text-sm text-left">
                <thead className="bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-200">
                    <tr>
                        <th className="px-4 py-3 font-semibold">Pos THR</th>
                        <th className="px-4 py-3 text-right font-semibold">Total THR (Tahunan)</th>
                        <th className="px-4 py-3 text-right font-semibold">Target Simpanan (Akumulasi)</th>
                        <th className="px-4 py-3 w-48 font-semibold">Progress</th>
                        <th className="px-4 py-3 font-semibold">Status</th>
                        <th className="px-4 py-3 text-center font-semibold w-32">Aksi</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-[var(--rw-border)] dark:divide-gray-700 bg-[var(--rw-bg-card)] dark:bg-gray-900">
                    {data.length === 0 ? (
                        <tr><td colSpan={6} className="text-center py-8 text-gray-500 italic">Belum ada budget THR tahun ini.</td></tr>
                    ) : (
                        data.map((item) => (
                            <tr key={item.id} className="hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-800 transition-colors">
                                <td className="px-4 py-3 font-medium text-gray-900 dark:text-gray-100">
                                    {item.category_name}
                                </td>
                                <td className="px-4 py-3 text-right text-gray-700 dark:text-gray-300 font-mono">
                                    {formatRp(item.total_thr)}
                                    <div className="text-[10px] text-gray-400">Target: {formatRp(item.monthly_target)}/bln</div>
                                </td>
                                <td className="px-4 py-3 text-right text-gray-700 dark:text-gray-300">
                                    {formatRp(Math.min(item.accumulated_amount, item.total_thr))}
                                </td>
                                <td className="px-4 py-3 align-middle">
                                    <div className="flex flex-col gap-1 w-full">
                                        <div className="flex justify-between text-[10px] text-gray-500">
                                            <span>{Math.round(Math.min(item.progress_percentage, 100))}%</span>
                                        </div>
                                        <div className="w-full h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                                            <div
                                                className={`h-full rounded-full transition-all duration-500 ${getProgressColor(item.status)}`}
                                                style={{ width: `${Math.min(item.progress_percentage, 100)}%` }}
                                            />
                                        </div>
                                    </div>
                                </td>
                                <td className="px-4 py-3">
                                    <Badge variant="outline" className={`${getStatusColor(item.status)} border whitespace-nowrap`}>
                                        {item.status}
                                    </Badge>
                                    {item.paid_at && (
                                        <div className="text-[10px] text-gray-500 mt-1">
                                            Paid: {new Date(item.paid_at).toLocaleDateString('id-ID')}
                                        </div>
                                    )}
                                </td>
                                <td className="px-4 py-3 text-center flex justify-center gap-2">
                                    {item.status !== 'PAID' && (
                                        <>
                                            <Button variant="ghost" size="icon" onClick={() => onEdit(item)} title="Edit Budget">
                                                <Edit className="w-4 h-4 text-blue-600" />
                                            </Button>

                                            <AlertDialog>
                                                <AlertDialogTrigger asChild>
                                                    <Button variant="ghost" size="icon" className="hover:bg-green-100 text-green-600" title="Bayar THR">
                                                        <Wallet className="w-4 h-4" />
                                                    </Button>
                                                </AlertDialogTrigger>
                                                <AlertDialogContent>
                                                    <AlertDialogHeader>
                                                        <AlertDialogTitle>Bayar THR?</AlertDialogTitle>
                                                        <AlertDialogDescription>
                                                            Tindakan ini akan mencatat transaksi PENGELUARAN sebesar <strong>{formatRp(item.total_thr)}</strong> ke dalam modul Keuangan.
                                                            Status akan berubah menjadi PAID. Tindakan ini tidak dapat dibatalkan.
                                                        </AlertDialogDescription>
                                                    </AlertDialogHeader>
                                                    <AlertDialogFooter>
                                                        <AlertDialogCancel>Batal</AlertDialogCancel>
                                                        <AlertDialogAction onClick={() => onPay(item.id)} className="bg-green-600 hover:bg-green-700">
                                                            Ya, Bayar THR
                                                        </AlertDialogAction>
                                                    </AlertDialogFooter>
                                                </AlertDialogContent>
                                            </AlertDialog>

                                            <AlertDialog>
                                                <AlertDialogTrigger asChild>
                                                    <Button variant="ghost" size="icon" className="hover:bg-red-100 text-red-600" title="Hapus">
                                                        <Trash2 className="w-4 h-4" />
                                                    </Button>
                                                </AlertDialogTrigger>
                                                <AlertDialogContent>
                                                    <AlertDialogHeader>
                                                        <AlertDialogTitle>Hapus Budget THR?</AlertDialogTitle>
                                                        <AlertDialogDescription>
                                                            Apakah Anda yakin ingin menghapus budget THR <strong>{item.category_name}</strong> tahun {item.year} sebesar <strong>{formatRp(item.total_thr)}</strong>? 
                                                            Data yang sudah dihapus tidak dapat dikembalikan.
                                                        </AlertDialogDescription>
                                                    </AlertDialogHeader>
                                                    <AlertDialogFooter>
                                                        <AlertDialogCancel>Batal</AlertDialogCancel>
                                                        <AlertDialogAction onClick={() => onDelete(item.id)} className="bg-red-600 hover:bg-red-700">
                                                            Hapus
                                                        </AlertDialogAction>
                                                    </AlertDialogFooter>
                                                </AlertDialogContent>
                                            </AlertDialog>
                                        </>
                                    )}
                                    {item.status === 'PAID' && (
                                        <AlertDialog>
                                            <AlertDialogTrigger asChild>
                                                <Button variant="ghost" size="sm" className="hover:bg-orange-100 text-orange-600" title="Batalkan Pembayaran">
                                                    <RefreshCw className="w-4 h-4 mr-1" />
                                                    Batal Bayar
                                                </Button>
                                            </AlertDialogTrigger>
                                            <AlertDialogContent>
                                                <AlertDialogHeader>
                                                    <AlertDialogTitle>Batalkan Pembayaran THR?</AlertDialogTitle>
                                                    <AlertDialogDescription>
                                                        Apakah Anda yakin ingin membatalkan pembayaran THR? 
                                                        Transaksi pengeluaran sebesar <strong>{formatRp(item.total_thr)}</strong> akan dihapus dari Keuangan, 
                                                        dan kas akan bertambah kembali. Status akan kembali ke PLANNED.
                                                    </AlertDialogDescription>
                                                </AlertDialogHeader>
                                                <AlertDialogFooter>
                                                    <AlertDialogCancel>Batal</AlertDialogCancel>
                                                    <AlertDialogAction onClick={() => onCancelPay(item.id)} className="bg-orange-600 hover:bg-orange-700">
                                                        Ya, Batalkan Pembayaran
                                                    </AlertDialogAction>
                                                </AlertDialogFooter>
                                            </AlertDialogContent>
                                        </AlertDialog>
                                    )}
                                </td>
                            </tr>
                        ))
                    )}
                </tbody>
            </table>
            </div>
        </div>
    );
}
